(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-flashattention-fast-and-memory-effic-2022"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-1\">一 · 一个在线服务的现场：长上下文请求把 GPU 拖进带宽墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-2\">二 · 旧方案的三重代价：显存平方增长、HBM 往返、反向的重算放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-3\">三 · 旧方案在推理栈里的连锁反应：批调度、KV cache 与分离式部署都被牵连</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-4\">四 · 为什么旧方案的修补路线走不通：近似、稀疏与低精度的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-5\">五 · 代价的边界条件：什么时候旧方案“够用”，什么时候必须换</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-6\">六 · 问题定义收束：一个精确、IO 感知的算子级替代</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-7\">七 · 负载形态先于算子选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-8\">八 · 批大小与并发的双向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-9\">九 · SLO 与长尾：尾延迟对分块更敏感</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-10\">十 · 方案反过来限制负载：准入与路由</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-11\">十一 · 可核查测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-12\">十二 · 负载形态如何反向约束分块算子：边界、失效条件与可核查口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-13\">十三 · 从在线 softmax 的数值骨架看累加精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-14\">十四 · 核心 kernel 的数据类型阶梯：FP16/BF16 到 FP8 再到 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-15\">十五 · 误差如何沿分块链累积，以及重计算的精度含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-16\">十六 · Blackwell 的 tcgen05、TMEM 与 2-SM MMA 对分块算子的改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-17\">十七 · 精度与分块尺寸的联合调参：一个可执行的判断顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-18\">十八 · 分块尺寸、精度链与 Blackwell 第五代 Tensor Core 的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-19\">十九 · 显存账本的三个账户与一条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-20\">二十 · 分页：把斜率项从连续数组变成块表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-21\">二十一 · 压缩、复用、卸载：三条不同的省法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-22\">二十二 · 带宽瓶颈的位置：预填与解码不是同一道题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-23\">二十三 · 一个可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-24\">二十四 · 分块注意力的边界：SRAM 配额、线性账本与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-25\">二十五 · 从算子分块到请求分块：调度层的块边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-26\">二十六 · Chunked prefill：把预填的平方级压力摊平</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-27\">二十七 · 优先级与抢占：显存不足时的调度决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-28\">二十八 · 分离式预填/解码：把两种负载放到不同资源池</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-29\">二十九 · 尾延迟怎么压：从均值指标到分位数约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-30\">三十 · 分块算子的调度边界：连续批处理与 chunked prefill 下的块尺寸、抢占与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-31\">三十一 · 切分维度与通信原语的对应关系</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-32\">三十二 · NVLink 5 与 NVSwitch：把 All-Reduce 压到可接受区间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-33\">三十三 · All-to-All 的不规则性：EP 是通信瓶颈的高发区</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-34\">三十四 · NIXL 传输：把 KV 搬移从计算路径上剥离</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-36\">三十六 · 当分块注意力遇上多卡切分：通信成为瓶颈的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-37\">三十七 · 精度塌陷：在线 softmax 的数值边界与量化叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-38\">三十八 · OOM 与 SRAM 溢出：块尺寸的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-39\">三十九 · 批抖动与尾延迟：变长批的分块失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-40\">四十 · 静默降级：收益消失而不报错</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-41\">四十一 · 监控面与回滚顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-42\">四十二 · 分块算子的失效面：从 SRAM 溢出到端到端倒挂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-43\">四十三 · 基准口径的第一原则：先固定“被测量”，再谈数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-44\">四十四 · 模型与序列长度：收益的定义域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-45\">四十五 · 硬件档位：SRAM 容量与带宽配比决定块尺寸，块尺寸决定一切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-46\">四十六 · batch 与并发：填充浪费与 SRAM 驻留压力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-47\">四十七 · 指标：TTFT、TPOT、吞吐、显存、功耗各自的陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-48\">四十八 · 哪些提升不可比：一张负面清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-49\">四十九 · 基准口径：分块注意力的收益边界与不可比数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-50\">五十 · 迁移到解码阶段：Q 块退化为单行，收益结构反转</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-51\">五十一 · 迁到变长批与连续批处理：块边界与调度器必须对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-52\">五十二 · 迁到量化与低精度：在线 softmax 的数值边界要重估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-53\">五十三 · 迁到多卡与分离式部署：分块边界与通信粒度耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-54\">五十四 · 规模上限与不适用场景：三条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-flashattention-fast-and-memory-effic-2022-sec-55\">五十五 · 迁移边界：分块收益在何处失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:561px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560.8 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入后按序列切分为 Q 块，K、V 按列分块，块尺寸由片上 SRA…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">外层循环遍历 K、V 块，内层循环遍历 Q 块，块对块做矩阵乘得到局部…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对局部分数做在线 softmax：更新运行最大值，重标定已有累加器，再…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">累加器与运行统计量保留在片上，仅最终输出块写回 HBM，避免完整注意力…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">反向传播时按块重算前向中间量，结合输出梯度逐块求 Q、K、V 梯度。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">最终输出按块拼接返回，供后续层或解码阶段使用。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-1\">一 · 一个在线服务的现场：长上下文请求把 GPU 拖进带宽墙</h3>\n<p>设想一个已经上线的对话式推理服务：单卡部署一个中等规模模型，SLO 写得很清楚——首 token 延迟不超过若干百毫秒，长上下文请求的吞吐要能撑住峰值并发。请求进来时，绝大多数是短问短答，但每天总有那么一批请求携带几万 token 的文档、代码库或对话历史。这批请求在旧方案下会呈现出一种很别扭的形态：GPU 的矩阵乘单元利用率并不高，SM 却在大量时间里等待显存返回数据；单条长请求的延迟随序列长度上升得比预期快，而且它一进来就把同批其他请求的尾延迟一起拖长。运维侧看到的不是“算力不够”，而是“算力有富余但吞吐上不去”。这就是 FlashAttention 之前推理栈的真实痛点现场：注意力算子在长序列上被 HBM 读写而非乘加算力卡住。</p>\n<p>要理解这个现场，得先把旧方案的做法摆清楚。标准注意力实现（也就是论文所称的 standard attention）在 GPU 上的执行路径是：从 HBM 读出 Q、K、V，算出分数矩阵 S=QKᵀ，把 S 完整写回 HBM；再读回 S，做 softmax 得到概率矩阵 P，把 P 写回 HBM；再读回 P 与 V，做 PV 得到输出 O。每一步都是一次完整的 HBM 往返，中间产物全部落盘。序列长度为 N 时，S 与 P 各是 N×N 的矩阵，显存占用随 N 平方增长；HBM 读写量同样随 N 平方增长。当 N 从几千涨到几万，乘加量是 O(N²d) 线性于 d，而 HBM 访问量是 O(N²) 且带着巨大的常数因子——两者量级关系一旦反转，算子就从算力受限滑进带宽受限。</p>\n<p>把这个代价放到在线服务里量化：一条长请求的注意力层需要物化 N×N 的中间矩阵，若同时驻留多条请求，显存很快被这些本可以不存在的中转数据吃掉，能留给 KV cache 与批并发的空间被压缩，连续批处理的批大小被迫调小，吞吐随之下降。更麻烦的是尾延迟：长请求的注意力阶段占用显存带宽的时间远长于其占用算力的时间，同一张卡上的短请求即使算力空闲也要排队等带宽，SLO 的 P99 被单条长请求拉爆。这不是调调度策略能解决的，因为瓶颈在算子内部的数据流，而不在批的组织方式。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-2\">二 · 旧方案的三重代价：显存平方增长、HBM 往返、反向的重算放大</h3>\n<p>旧方案的第一重代价是显存。完整注意力矩阵必须物化，其占用为 O(N²)。在推理侧，这意味着长上下文请求的峰值显存不由模型权重或 KV cache 决定，而由注意力中间矩阵决定；在训练与需要反向的场景里，这个矩阵还要被保存下来供反向使用，占用进一步放大。第二重代价是 HBM 读写：S 写回、S 读回、P 写回、P 读回，四次 N×N 级别的搬运，每一次都在消耗本已紧张的 HBM 带宽。第三重代价出现在反向：标准实现为了求梯度必须保留前向的中间矩阵，显存占用与序列长度平方相关，且反向本身还要再读一遍这些矩阵。</p>\n<p>用公式把“为什么非改不可”写清楚。设单次 HBM 访问的代价远高于一次片上乘加，则算子总时间近似为</p>\n<div class=\"formula\">$$T \\approx \\max\\!\\left(\\frac{\\text{FLOPs}}{\\text{peak FLOPS}},\\ \\frac{\\text{Bytes}_{\\text{HBM}}}{\\text{HBM bandwidth}}\\right)$$</div>\n<p>标准注意力中 Bytes_HBM 含 Q、K、V、O 的线性项与 S、P 的平方项，N 增大时平方项主导，T 被第二项锁死；而 FLOPs 只是 O(N²d)，d 固定时算力项增长慢于带宽项。这就是“算力有富余、吞吐上不去”的数学解释。工程判断因此很直接：要提速，必须削减 Bytes_HBM 中的平方项，而不是去堆算力或换更快的矩阵乘指令。</p>\n<p>具体例子：一条 N 很大的请求进入服务，旧方案下注意力层需要把 N×N 的分数矩阵写回再读回，这部分搬运时间与 N² 成正比；同一时刻批内其他请求的 KV cache 读取也要抢带宽，于是整批的 token 生成节奏被这一条请求拖慢。若把这条请求单独隔离到一张卡上，尾延迟好转但卡利用率崩掉；若放进批里，P99 崩掉。这个两难正是旧方案逼出来的调度困境，也是论文要解决的算子级问题。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-3\">三 · 旧方案在推理栈里的连锁反应：批调度、KV cache 与分离式部署都被牵连</h3>\n<p>旧方案的代价不会停留在单个算子里，它会沿着推理栈向上传导。第一站是批调度：连续批处理的前提是每条请求的显存占用可预测、可拼装，而 O(N²) 的注意力中间矩阵让长请求的瞬时占用剧烈波动，调度器要么保守地限制批大小，要么在长请求到来时触发抢占与重算，两者都伤吞吐。第二站是 KV cache 布局：KV cache 本身是线性于序列长度的，但旧算子执行时还要额外开辟平方级的临时空间，显存预算被切成两块，分页管理的粒度与预留策略被迫为最坏情况留余量，实际可用的 cache 容量被压低。第三站是分离式预填/解码：预填阶段处理的正是长序列，旧方案在这一段最痛，预填节点成为整个流水线的瓶颈，解码节点则因等待预填结果而空转。</p>\n<p>这里要强调一个容易被忽略的点：旧方案的瓶颈不是“某一次矩阵乘太慢”，而是“数据在存储层级之间来回搬”。GPU 的存储层级是 HBM—L2—SRAM/寄存器，片上 SRAM 容量有限但带宽极高，HBM 容量大但带宽相对算力紧张。标准实现把中间矩阵放在 HBM，等于让最贵的一层存储承担了最频繁的读写；而矩阵乘本身完全可以在片上完成。旧方案没有利用这个层级差异，这才是非改不可的根本原因。任何只在 HBM 层面做优化的尝试——比如换更大的卡、提高 HBM 频率、把中间矩阵换成更低精度——都只是把平方项的系数调小，没有改变平方增长的趋势。</p>\n<p>代价的定性表述可以这样落地：在长序列、带宽相对算力更紧张的配置下，旧方案的端到端吞吐由 HBM 带宽而非算力决定，增加算力或提高 occupancy 都无法转化为吞吐；在短序列下平方项不显著，旧方案的额外开销相对可控，这也是为什么该问题长期被当作“长序列专属问题”而未被系统性处理。推理系统一旦把长上下文作为卖点，这个“专属问题”就变成主路径问题。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-4\">四 · 为什么旧方案的修补路线走不通：近似、稀疏与低精度的边界</h3>\n<p>在 FlashAttention 之前，工程上对长序列注意力的主流修补路线有三类：近似注意力（稀疏化、低秩、局部窗口）、低精度中间矩阵、以及把中间矩阵分块但仍落盘。这三类路线各有其代价，且都没有触及“精确”与“IO”这两个关键点。近似方法改变了数学结果，在需要严格对齐的推理场景里引入不可控误差，且稀疏模式与真实注意力分布不匹配时质量下降明显；低精度中间矩阵把平方项的字节数调小，但读写次数不变，带宽瓶颈依旧，且 softmax 的数值稳定在低精度下更难保证；分块但仍落盘的做法减少了峰值显存，却没有减少 HBM 往返总量，带宽项仍是平方级。</p>\n<p>论文的立场在这条修补谱系里很清晰：不引入近似、不稀疏化，保持数学结果完全一致，只改数据流。这个立场对推理栈的意义在于可组合性——精确算子可以与 KV cache 分页、批调度、量化等机制正交叠加，而不需要为“近似误差”单独建一套质量评估与回退逻辑。反过来说，把精确注意力与近似方法混谈是常见的工程误判：量化或稀疏化引入的误差必须单独评估，不能归因于分块机制，也不能用分块的收益去掩盖近似的质量损失。</p>\n<p>具体到数值层面，旧方案在 softmax 上还有一个隐性代价：完整矩阵物化后做全局 softmax，需要先求全局最大值再归一化，这要求对整行分数做一次完整遍历；若分数矩阵在 HBM，这次遍历就是又一次平方级读。修补路线里的“分块但仍落盘”无法回避这次读，因为归一化因子必须基于全局统计量。这恰恰指向了论文的核心机制：把归一化改成在线的、可合并的，才能让分块真正摆脱对完整矩阵的依赖。这个机制的细节属于后续部分，此处只需指出旧方案在数值路径上也被平方级 IO 绑住。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-5\">五 · 代价的边界条件：什么时候旧方案“够用”，什么时候必须换</h3>\n<p>把旧方案的痛点讲透，还要讲清它的边界，否则工程上容易走向另一个极端——把分块收益当作无条件加速。旧方案在短序列下是合理的：平方项不显著，HBM 往返量小，算子接近算力受限，此时引入分块与重计算带来的调度开销、片上占用压力可能抵消收益，端到端延迟不降反升。判断阈值不能照搬论文数字（材料未给出具体加速比、显存下降数值与序列长度阈值），必须在目标硬件上实测：测的是 HBM 读写量随序列长度的曲线拐点，以及片上占用溢出与块调度空转的监控指标。</p>\n<p>边界条件还与硬件档位绑定。分块尺寸受片上 SRAM 容量硬约束：块过大无法驻留导致溢出，块过小则数据复用率与并行度下降。不同档位的 SRAM 容量与 HBM 带宽配比不同，同一套块尺寸不能跨档照搬，否则会出现占用溢出或复用率下降的失败模式。推理服务在做容量规划时，需要把“带宽瓶颈程度”作为一个显式变量：序列越长、HBM 带宽相对算力越紧张，分块收益越明显；反之则应以旧方案或轻量分块为主，避免为不存在的瓶颈付出重计算代价。</p>\n<p>还有一个与批相关的边界：批内序列长度不齐时需按最长序列分块，存在填充浪费；并发上升时片上 SRAM 与寄存器压力增大，需限制同时驻留的块数以避免占用溢出。这些约束意味着分块算子的收益不是单调的，它与批的组织方式、序列长度分布、SLO 对尾延迟的敏感度共同决定。在线服务场景里，首 token 延迟与长序列吞吐是两个不同的目标，带宽瓶颈场景下分块算子对尾延迟更敏感——因为长请求的注意力阶段一旦被优化，尾延迟的改善最直接，但短请求的调度开销也可能被放大。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-6\">六 · 问题定义收束：一个精确、IO 感知的算子级替代</h3>\n<p>把现场、代价、连锁反应与边界条件收束成一个问题定义：需要一个注意力算子，在不改变数学结果的前提下，把 HBM 读写从平方级压到与序列长度线性相关，把显存占用从平方级降为线性级，并且这个算子要能嵌进现有推理栈而不破坏批调度与 KV cache 布局。这个定义排除了近似路线，也排除了“只调系数”的修补路线，指向的是数据流的重新组织——按块把 Q、K、V 载入片上 SRAM，在片上完成块乘与在线 softmax 合并，完整注意力矩阵从不落盘；反向以重计算替代中间量保存。</p>\n<p>这个替代方案的工程代价在问题定义阶段就要写明：分块尺寸受 SRAM 容量约束，收益依赖带宽瓶颈程度，材料未给出具体加速比与显存数字，部署容量规划不能直接引用论文数字。换言之，论文给出的是算子级范式与机制，不是可以直接抄进配置文件的参数。推理团队接手时的第一件事不是照搬块大小，而是在目标硬件上测出 HBM 读写量与片上占用的实际曲线，再决定分块粒度与是否启用重计算。</p>\n<p>最后落在一个具体机制上：旧方案的四次 N×N 级 HBM 往返（S 写、S 读、P 写、P 读）在问题定义里被明确列为要消除的对象，替代路径只保留 Q、K、V、O 与 softmax 统计量的线性级读写。这个“消除平方级往返”的判断，就是后续所有分块、在线归一化与重计算设计的出发点；它也是推理栈在长上下文场景下从带宽墙里脱身的前提。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-7\">七 · 负载形态先于算子选型</h3>\n<p>把 FlashAttention 放进推理系统，第一件要问的不是块多大，而是请求长什么样。输入长度分布决定分块数量与 HBM 读写占比：标准注意力把完整注意力矩阵写回 HBM，显存随序列长度平方增长，长序列下 HBM 读写成为主要瓶颈而非矩阵乘算力；分块算子把 HBM 只读写 Q、K、V、O 与 softmax 统计量，收益正比于“被省掉的中间矩阵流量”。因此负载刻画必须给出长度直方图而非均值：均值掩盖长尾，而长尾正是平方级显存与带宽压力的来源。可核查口径是：按请求记录输入 token 数、输出 token 数、到达时间戳，按分钟聚合出 P50/P90/P99 与最大值，同时记录同一批次内长度极差。极差直接对应填充浪费——批内序列长度不齐时需按最长序列分块，短请求被迫按长请求的块数走，SRAM 驻留与循环次数被拉高。并发数则要与长度联合统计：并发上升时片上 SRAM 与寄存器压力增大，需限制同时驻留的块数以避免占用溢出，这一约束在长度分布偏长时更早触发。</p>\n<div class=\"formula\">$$\\text{IO}_{\\text{saved}} \\;\\propto\\; \\sum_{i} N_i^{2} \\;-\\; \\sum_{i} c\\,N_i,\\quad c=\\text{每 token 的 Q/K/V/O 与统计量字节数}$$</div>\n<p>式子只作定性配比：被省掉的是与 $N_i^2$ 同阶的中间矩阵流量，留下的是与 $N_i$ 线性的张量流量。工程含义是，长度分布越偏长、越集中，分块收益越稳定；长度分布短而散，重计算与调度开销可能抵消收益。测量上应把“HBM 读写字节数”作为一等指标，用硬件计数器或 profiler 的显存流量口径采集，而不是只看 kernel 时间——后者会把带宽瓶颈与算力瓶颈混在一起。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-8\">八 · 批大小与并发的双向约束</h3>\n<p>批大小影响 Q 块并行度：Q 按行切块后，块间可并行，批内请求数越多，可并行的 Q 块越多，SM 占用越饱满。但批大小同时被 SRAM 容量反向限制：每个驻留块要占用片上 SRAM 与寄存器，块尺寸由 SRAM 容量选定，块过大无法驻留导致溢出，块过小则数据复用率与并行度下降。于是存在一个由硬件档位决定的可行域：批大小 × 块尺寸 × 同时在飞块数不能超过片上容量。可核查口径是记录每次 kernel 启动的块尺寸、网格维度、占用率与溢出/回退事件；若出现占用溢出，表现为核内循环被迫缩小块或复用率下降，端到端表现为吞吐不升。连续批处理场景下，批是动态拼装的，长度极差随时间变化，因此应把“批内长度极差”的分布也纳入监控，而不只监控批大小均值。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>对分块算子的作用</th><th>可核查口径</th></tr></thead><tbody><tr><td>输入长度分布</td><td>决定分块数量与 HBM 读写占比</td><td>P50/P90/P99/最大值直方图</td></tr><tr><td>批内长度极差</td><td>决定填充浪费与块循环次数</td><td>每批 max−min token 数</td></tr><tr><td>并发数</td><td>抬高 SRAM 与寄存器驻留压力</td><td>占用率、溢出/回退计数</td></tr><tr><td>到达间隔</td><td>决定批拼装窗口与空转</td><td>队列等待时长、块调度空转率</td></tr></tbody></table>\n<p>具体例子：一个在线服务同时收到一条长文档问答与若干条短对话，若按最长序列分块，短请求的 Q 块数被拉长到与长请求同量级，片上驻留被长请求占满，短请求的尾延迟被拖高。此时要么限制单批长度极差，要么把长请求单独成批——这是负载塑造方案的直接体现。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-9\">九 · SLO 与长尾：尾延迟对分块更敏感</h3>\n<p>SLO 关注首 token 延迟与长序列吞吐。带宽瓶颈场景下分块算子对尾延迟更敏感：长请求的块循环次数多，单请求占用 SM 时间长，若与短请求同批，短请求必须等长请求的块全部走完才能拿到输出块。可核查口径是把首 token 延迟按请求长度分桶统计，而不是全局平均；同时记录“同批内最长请求的块数”与“该批首 token 延迟”的散点关系，用来判断尾延迟是否由批内长度极差驱动。另一个口径是输出块写回 HBM 的时序：分块算子只在遍历完所有 K、V 块后用运行归一化因子 l 归一化并写回该 Q 块输出，因此首 token 的可获得时间与块循环总时长绑定，缩短块循环是降尾延迟的直接手段，而块尺寸又受 SRAM 硬约束，二者构成张力。</p>\n<div class=\"formula\">$$T_{\\text{first}} \\;\\approx\\; \\underbrace{\\frac{N}{B_q}}_{\\text{Q 块数}}\\cdot\\underbrace{\\frac{N}{B_{kv}}}_{\\text{K/V 块数}}\\cdot t_{\\text{block}} \\;+\\; t_{\\text{writeback}}$$</div>\n<p>该式只表达块循环次数与单块代价的乘积结构，不给出具体时间。工程判断是：当 P99 长度远高于 P50 时，尾延迟由块循环次数主导，此时应优先按长度分桶路由，而不是一味增大批大小；增大批只提升吞吐，不改善尾延迟，甚至因驻留压力上升而恶化。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-10\">十 · 方案反过来限制负载：准入与路由</h3>\n<p>分块算子一旦定型，块尺寸与 SRAM 配比就固定，系统对负载的接纳能力随之被限定。可核查的工程动作是设置长度准入阈值：超过某长度的请求走独立队列或专用实例，避免其块循环占满片上驻留而挤压短请求。阈值不能引用论文数字——材料未给出具体加速比、显存下降数值与序列长度阈值，部署容量规划不能直接引用论文数字，需在目标硬件上实测。测量口径为：在目标硬件上扫长度分档，记录每档的 HBM 读写字节数、块调度空转率与端到端延迟，找出收益由正转负的拐点，作为准入阈值。另一条限制是量化组合：该算子为精确注意力，不引入近似或稀疏化，可与 KV cache 分页、批调度等推理机制正交组合，但组合时需重新评估 SRAM 占用；量化后需重估块内累加精度与在线 softmax 数值稳定，误差需单独评估，不能归因于分块机制。</p>\n<p>具体例子：若把 KV cache 分页粒度设得与 K/V 列块边界不对齐，块载入会跨页，HBM 读写从连续变为碎片化，带宽利用率下降，分块收益被吃掉。可核查口径是记录每次块载入的跨页次数与有效带宽，跨页次数上升即说明分页粒度与块边界失配。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-11\">十一 · 可核查测量口径清单</h3>\n<p>负载侧：输入/输出 token 数直方图、批内长度极差、到达间隔、并发峰值、队列等待时长。算子侧：块尺寸、网格维度、占用率、溢出/回退计数、块调度空转率、跨页次数。带宽侧：HBM 读写字节数（区分 Q/K/V/O 与统计量）、有效带宽、块载入连续性。延迟侧：首 token 延迟按长度分桶、每 token 延迟、P99 与最大值。吞吐侧：每秒完成请求数与每秒处理 token 数，均按长度分桶报告。所有指标须与同一时间窗的负载直方图配对，否则无法判断吞吐变化是负载漂移还是方案变化。材料未给出具体指标阈值，阈值须在目标硬件上以拐点法实测确定。</p>\n<ul><li>禁止把分块收益当作无条件加速：短序列或算力受限场景下重计算与调度开销可能使端到端延迟不降反升，需以长度分档实测验证。</li><li>禁止照搬块尺寸：不同硬件档位 SRAM 与带宽配比不同，块尺寸需逐档实测，否则出现占用溢出或复用率下降。</li><li>禁止把精确注意力与近似方法混谈：量化或稀疏化引入的误差需单独评估。</li></ul>\n<p>最后落在机制上：在线 softmax 维护每个 Q 块的运行最大值 m 与运行归一化因子 l，新块到达时用新最大值重标定已累加分子项，保证分块合并与整块计算数学等价；这一等价性意味着负载侧的长度分布不会改变数值结果，只会改变块循环次数与 HBM 流量配比。因此容量规划的正确姿势是把长度直方图与块循环次数绑定建模，用实测拐点划定准入阈值，而不是用单一平均长度估算吞吐。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-12\">十二 · 负载形态如何反向约束分块算子：边界、失效条件与可核查口径</h3>\n\n<p>FlashAttention 的收益不是算子自带的常数，而是输入负载与硬件配比共同决定的函数。序列长度分布首先决定 HBM 读写占比：短序列下 Q、K、V 本身就能被片上 SRAM 容纳，标准实现物化注意力矩阵的额外开销有限，分块带来的在线 softmax 重标定与核内循环调度反而成为纯开销；序列拉长后，完整注意力矩阵的 O(N²) 写回才成为主导项，分块收益随之显现。批大小则决定 Q 块的并行度：批内序列长度不齐时，核函数按最长序列切块，短请求被迫填充到同一块网格，填充部分既占 SRAM 又空转算力。并发上升时同时驻留的块数增加，片上 SRAM 与寄存器压力上升，必须限制在飞块数以避免占用溢出——这是分块算子对负载的直接反制：它不是被动接受任意并发，而是用 SRAM 容量给并发设了一个隐式上限。</p>\n\n<p>可核查的测量口径应围绕 IO 而非算力展开。核心量是 HBM 读写字节数与理论下界之比：分块前向只读写 Q、K、V、O 与 softmax 统计量，其字节量随序列长度线性增长，而标准实现额外写回 N² 的注意力矩阵。定义 IO 放大系数</p>\n<div class=\"formula\">$$\\rho=\\frac{B_{\\text{HBM}}^{\\text{实测}}}{B_{\\text{HBM}}^{\\text{下界}}},\\quad B_{\\text{HBM}}^{\\text{下界}}\\approx 4N d\\,\\text{bytes}\\ \\text{(Q,K,V,O 各一份)}$$</div>\n<p>ρ 接近 1 说明分块已把冗余写回压掉，ρ 明显大于 1 则指向块尺寸过小导致的重复载入或统计量额外往返。与之配对的是片上占用溢出计数与块调度空转率：前者反映块尺寸是否超出 SRAM 容量，后者反映批内长度不齐造成的填充浪费。三者合起来才能判断一次部署里分块是净收益还是净开销，单看端到端吞吐会被批调度与解码阶段掩盖。</p>\n\n<p>失效条件可以列成一张按负载形态分档的表，部署时逐档实测而非照搬块尺寸：</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>主要代价</th><th>观测口径</th></tr></thead><tbody><tr><td>短序列、高并发</td><td>在线 softmax 重标定与调度开销占主导</td><td>ρ 接近 1 但端到端延迟不降</td></tr><tr><td>长序列、批内等长</td><td>收益最大，受 SRAM 容量约束块尺寸</td><td>ρ 显著下降，溢出计数为零</td></tr><tr><td>变长批、长尾请求</td><td>按最长序列填充，短请求空转</td><td>块调度空转率随尾长上升</td></tr><tr><td>算力受限档位</td><td>反向重计算多一次前向块计算</td><td>反向时间占比上升，显存线性下降</td></tr></tbody></table>\n<p>长尾请求是这套方案最敏感的一类：SLO 关注首 token 延迟时，尾请求按最长序列切块，其块网格远大于主体请求，单请求占用 SRAM 的时间被拉长，挤占同批其他请求的驻留空间。此时分块算子与连续批处理的组合需要重新评估——分块边界与 KV cache 分页粒度不对齐会产生额外的块重载，而精确注意力本身不引入近似，量化或稀疏化带来的误差必须单独归因，不能记在分块机制账上。工程判断落在具体机制上：块尺寸应按目标硬件的 SRAM 容量与 HBM 带宽比逐档标定，并把 ρ、溢出计数、空转率作为上线前的准入门槛，而不是把论文的分块思路当作无条件加速直接套用。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-13\">十三 · 从在线 softmax 的数值骨架看累加精度</h3>\n<p>分块注意力在数值上真正脆弱的地方不是块乘本身，而是运行统计量的更新顺序。前向对每个 Q 行块维护一对状态：运行最大值 <em>m</em> 与运行归一化因子 <em>l</em>，每来一个 K、V 列块就做一次重标定。写成递推形式，设第 <em>t</em> 个块到达时局部分数为 <em>s<sub>t</sub></em>、块内最大值为 <em>m<sub>t</sub></em>，则</p>\n<div class=\"formula\">$$m^{(t)}=\\max\\!\\left(m^{(t-1)},\\,m_t\\right),\\quad \\alpha=\\exp\\!\\left(m^{(t-1)}-m^{(t)}\\right),\\quad l^{(t)}=\\alpha\\,l^{(t-1)}+\\sum_{j\\in t}\\exp\\!\\left(s_j-m^{(t)}\\right)$$</div>\n<p>逐项解释：<em>m</em> 单调不减，因此 <em>α</em> ≤ 1，重标定只会把已累加的量往小里压，不会放大——这是数值稳定的关键，也是为什么必须用运行最大值而不是固定常数做偏移。<em>α</em> 与块内指数项都落在 (0,1]，累加器 <em>l</em> 的量级被约束在块数级别，不会随序列长度指数爆炸。分子累加器 <em>o</em> 同理按 <em>α</em> 缩放后再叠加 <em>exp(s−m)·v</em>。最终输出 <em>o/l</em> 与整块一次算完的结果数学等价，误差只来自浮点舍入。</p>\n<p>累加精度的工程判断在这里分叉。若 <em>l</em> 与 <em>o</em> 用与输入相同的 FP16 累加，长序列下块数增多，反复乘 <em>α</em> 与累加会积累舍入误差，且 <em>o</em> 的动态范围跨越多个数量级，FP16 的尾数位不够。实践中的做法是累加器用 FP32（或在 Blackwell 上走 Tensor Core 的 FP32 累加通路），输入块乘用低精度。代价是可测的：FP32 累加器使片上寄存器与 SRAM 占用翻倍，直接压缩可用的块尺寸，进而降低数据复用率；在 SRAM 容量固定的档位上，这是一笔用带宽换精度的交易。具体到一次长序列调用，若把 <em>o</em>、<em>l</em>、<em>m</em> 全部提到 FP32，块尺寸往往要下调一档，HBM 读写次数随之上升——精度不是免费的。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-14\">十四 · 核心 kernel 的数据类型阶梯：FP16/BF16 到 FP8 再到 NVFP4</h3>\n<p>FlashAttention 原始形态的输入是 FP16 或 BF16，块乘走 Tensor Core 的 FP16 输入、FP32 累加。两者在注意力里的差别不在算力而在动态范围：BF16 只有 8 位指数、7 位尾数，FP16 是 5 位指数、10 位尾数。注意力分数 <em>q·k<sup>T</sup></em> 在长序列上跨度大，BF16 的宽指数能容纳更大的分数范围而不溢出，代价是尾数少三位、单次块乘的相对误差更大；FP16 尾数更细但更容易在极端分数上饱和。选择哪一种，取决于该层分数分布是否已被观测过——这是部署时必须实测而不是照抄论文的点。</p>\n<p>再往下是 FP8（E4M3 与 E5M2 两种编码）与 Blackwell 的 NVFP4。FP8 的块乘吞吐相对 FP16 有成倍提升，但注意力对量化的敏感点集中在两处：一是 <em>q·k<sup>T</sup></em> 的分数在 softmax 前被指数放大，分数上的量化误差会被 <em>exp</em> 放大；二是 <em>v</em> 的量化误差直接进入输出。因此工程上常见的组合是 Q、K 用 FP8 做块乘、softmax 统计量与累加器保持 FP32，V 的精度按层敏感度单独决定。NVFP4 把尾数压到 4 位、配块级缩放因子，进一步把块乘带宽需求压低，但对注意力分数这种长尾分布，块级缩放因子的粒度选择直接决定分数误差是否被 <em>exp</em> 放大到不可接受。</p>\n<table class=\"mini\"><thead><tr><th>数据类型</th><th>注意力中的角色</th><th>主要风险</th><th>系统代价</th></tr></thead><tbody><tr><td>FP16</td><td>Q/K/V 块乘输入</td><td>极端分数饱和</td><td>基线吞吐与 SRAM 占用</td></tr><tr><td>BF16</td><td>Q/K/V 块乘输入</td><td>尾数少、块乘相对误差大</td><td>与 FP16 同级吞吐</td></tr><tr><td>FP8</td><td>Q/K 块乘，V 按层选</td><td>分数误差被 exp 放大</td><td>块乘吞吐提升、需重估块尺寸</td></tr><tr><td>NVFP4</td><td>块乘输入，配块级缩放</td><td>缩放粒度不当致分数失真</td><td>带宽需求最低、精度预算最紧</td></tr></tbody></table>\n<p>具体例子：一层 128 头、头维 128 的注意力，序列长度拉到使 K、V 块数达到数十个量级时，若 Q、K 降到 FP8，块乘的算力时间被压缩，但 <em>exp</em> 与重标定的标量运算并不随精度降低而变快，于是核内时间从块乘主导转向 softmax 标量主导——这时继续压精度收益递减，反而应把预算花在减少重标定次数或提高块尺寸上。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-15\">十五 · 误差如何沿分块链累积，以及重计算的精度含义</h3>\n<p>分块链上的误差有三个来源，必须分开归因，否则调参方向会错。第一是块乘误差：低精度输入使 <em>s<sub>j</sub></em> 带相对误差 <em>ε<sub>s</sub></em>，经 <em>exp</em> 后变为约 <em>ε<sub>s</sub></em>·|<em>s<sub>j</sub></em>−<em>m</em>| 的相对误差，分数绝对值越大放大越明显。第二是重标定误差：每次乘 <em>α</em> 引入一次舍入，块数 <em>T</em> 时误差随 <em>T</em> 线性累积，这是累加器必须用 FP32 的直接理由。第三是归一化误差：<em>o/l</em> 的除法在 <em>l</em> 很小时放大相对误差，而 <em>l</em> 恰是块内指数项之和，长序列上它随块数增长，通常不会太小，但在分数整体偏负的行上仍需警惕。</p>\n<div class=\"formula\">$$\\frac{\\delta \\exp(s-m)}{\\exp(s-m)}\\approx \\delta s,\\qquad \\left|\\delta l^{(T)}\\right|\\lesssim T\\,\\varepsilon_{\\text{acc}}\\,l^{(T)}$$</div>\n<p>第一式说明分数误差在指数后原样传递为相对误差，第二式说明累加误差随块数线性增长、与 <em>ε<sub>acc</sub></em>（累加器精度）成正比。两式合起来给出一个工程判断：降低块乘精度（放大 <em>δs</em>）与减少块数（缩小 <em>T</em>）是两条不同的误差控制路径，前者省带宽、后者省重标定次数，不能混为一谈。</p>\n<p>反向的重计算把精度问题又推进一步。反向不保存注意力矩阵，而是按同样分块顺序重算前向局部分数，再结合输出梯度求 Q、K、V 梯度。这里的关键是重算必须与前向使用完全相同的块尺寸、相同的累加精度与相同的重标定顺序，否则重算出的 <em>s</em> 与前向实际用过的 <em>s</em> 存在系统性偏差，梯度会带上一个不该有的偏置。代价是反向多一次前向块计算，算力开销上升；收益是显存从平方级降为线性级，且省掉了中间矩阵的 HBM 读写。在低精度部署下，这笔交易更划算：重算用的是同样的低精度块乘，算力便宜，而若保存中间矩阵则要按低精度存一份 O(N²) 数据，显存压力不减。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-16\">十六 · Blackwell 的 tcgen05、TMEM 与 2-SM MMA 对分块算子的改写</h3>\n<p>Blackwell（SM100/SM103）把 Tensor Core 的取数路径改了：tcgen05 系列指令的矩阵乘不再要求操作数从寄存器文件进出，而是以 Tensor Memory（TMEM）作为累加器与操作数的驻留区，由专门的异步 MMA 指令驱动。对分块注意力而言，这意味着累加器 <em>o</em> 可以长期驻留在 TMEM 而不是挤在寄存器里，寄存器压力下降，块尺寸的选择空间变大——原先受寄存器容量卡住的块尺寸，在 TMEM 档位上可以往上提一档，直接减少 HBM 读写轮次。</p>\n<p>2-SM MMA 是另一条改写路径：一对 SM 协同执行一次更大的矩阵乘，把块乘的粒度做大。对注意力来说，一个 Q 行块与一个 K 列块的乘积可以由两个 SM 分担，单次 MMA 的有效尺寸翻倍，块内数据复用率上升。代价是协同带来的同步开销与配对约束：两个 SM 必须同时空闲、共享同一块数据布局，块调度不能再各自为政。在批内序列长度不齐的场景下，配对会放大填充浪费——一个 SM 等另一个 SM 的长块，尾延迟变差。</p>\n<p>第五代 Tensor Core 的低精度通路与 TMEM 结合后，NVFP4 的块乘可以在保持 FP32 累加的同时把输入带宽压到最低。但这里有一个必须实测的配比问题：TMEM 容量、SRAM 容量与 HBM 带宽三者的比例决定了最优块尺寸，而不同档位（B200 与 B300、GB200 与 GB300 NVL72）的配比不同。把在一个档位上调好的块尺寸照搬到另一个档位，典型后果是 TMEM 或 SRAM 占用溢出导致核内循环退化，或块过小导致复用率下降——两种失败都不报错，只表现为吞吐不达预期。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-17\">十七 · 精度与分块尺寸的联合调参：一个可执行的判断顺序</h3>\n<p>把上面几条合起来，部署时的调参不是先定精度再定块尺寸，而是两者联合。可执行的顺序是：先测该层分数分布的最大绝对值与长尾程度，决定 Q、K 能否降到 FP8 或 NVFP4；再按累加器精度（FP32 必要与否）估算片上占用，反推块尺寸上限；然后在目标档位上实测 HBM 读写量与核内标量运算占比，判断瓶颈在块乘、softmax 标量还是 HBM。若标量占比高，说明精度已不是瓶颈，应优先提高块尺寸或减少重标定次数；若 HBM 占比高，才值得继续压精度。</p>\n<ul>\n<li>分数长尾重、<em>exp</em> 放大明显：Q、K 保持 FP16/BF16，把精度预算留给 V 与累加器。</li>\n<li>分数分布集中、长尾短：Q、K 可下探 FP8，累加器保持 FP32，块尺寸按 TMEM 容量上调。</li>\n<li>反向重算与前向必须同精度同块序，任何一处不一致都会给梯度引入系统偏置。</li>\n<li>换档位必重测块尺寸，TMEM/SRAM/HBM 配比变化使旧参数失效。</li>\n</ul>\n<p>具体到一个 GB300 NVL72 机架上的长序列预填场景：单请求序列极长、批很小，块数多、重标定次数多，此时把累加器提到 FP32、Q/K 保持 BF16、块尺寸按 TMEM 容量取上限，收益主要来自 HBM 读写轮次减少；而在高并发短序列的解码场景，块数少、重计算开销占比高，压精度换吞吐的意义大于调块尺寸。同一个算子，两种负载下的最优精度与块尺寸组合不同——这正是分块注意力在 Blackwell 上必须按负载形态而非按论文参数部署的原因。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-18\">十八 · 分块尺寸、精度链与 Blackwell 第五代 Tensor Core 的耦合边界</h3>\n<p>在线 softmax 的数学等价性只保证结果正确，不保证收益。真正决定端到端表现的是块尺寸与片上 SRAM 容量的配比：设块行数为 B<sub>r</sub>、块列数为 B<sub>c</sub>、头维度为 d，则一个 Q 块、一个 K/V 块与分数块、累加器需同时驻留片上，占用近似为 <span class=\"formula\">$$S_{\\text{onchip}}\\approx B_r d + 2B_c d + B_r B_c + B_r d$$</span> 其中前三项分别是 Q 块、K 与 V 块、分数块，末项是输出累加器。分数块项 B<sub>r</sub>B<sub>c</sub> 随两个块尺寸相乘增长，是最先撞上 SRAM 上限的一项；块过大直接溢出，块过小则 K/V 复用率与并行度同时下降。Blackwell 上这条约束被放大：tcgen05 与 TMEM 把累加器搬入张量内存，2-SM MMA 让两个 SM 协同承担一次更大的 MMA，单次 MMA 的 N 维更大，意味着 B<sub>c</sub> 可以取更大值而分数块仍受 SRAM 限制——调参空间不是变宽，而是从“寄存器压力”转移到“TMEM 容量与 SRAM 配比”，逐档实测不可避免。</p>\n<p>精度链是第二个边界。分块前向中，q<sub>i</sub>k<sub>j</sub><sup>T</sup> 以 FP16/BF16 输入进入第五代 Tensor Core，累加在 FP32 完成，随后减去运行最大值 m<sub>i</sub> 再取指数；m<sub>i</sub> 与 l<sub>i</sub> 必须以足够精度保留，否则重标定 exp(q<sub>i</sub>k<sub>j</sub><sup>T</sup>−m<sub>i</sub>)/l<sub>i</sub> 的分子项在块间合并时产生系统性偏差。切到 FP8 时，输入量化误差直接进入分数，指数放大误差；切到 NVFP4 时，尾数位更少，块内累加必须保持 FP32，且 m<sub>i</sub> 的重标定频率上升。代价是可量化的：低精度把 MMA 吞吐推高，但 softmax 统计量的读写与重标定次数增加，片上占用与指令开销上升；若为省 SRAM 缩小 B<sub>c</sub>，则 HBM 读写次数回升，抵消量化收益。工程判断是：量化收益必须与块尺寸联合调，单独换精度往往在长序列上才显现，短序列下重计算与调度开销已抵消分块收益，精度再降也救不回来。</p>\n<p>失效条件集中在三处。其一，短序列或算力受限场景：重计算多一次前向块计算，调度开销固定，分块收益依赖 HBM 带宽相对算力紧张的程度，序列不够长时端到端延迟可能不降反升。其二，批内序列长度不齐：按最长序列分块产生填充浪费，批大小上升时片上 SRAM 与寄存器压力增大，需限制同时驻留块数，否则占用溢出。其三，把精确注意力与近似方法混谈：该算子不改变数学结果，FP8/NVFP4 引入的误差需单独评估，不能归因于分块机制。系统代价可列成一张对照：</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>块偏大</th><th>块偏小</th></tr></thead><tbody><tr><td>SRAM/TMEM 占用</td><td>溢出风险，驻留块数受限</td><td>占用低，可多块并行</td></tr><tr><td>HBM 读写</td><td>K/V 复用高，读写占比低</td><td>复用率下降，读写回升</td></tr><tr><td>并行度与尾延迟</td><td>并行度低，尾延迟敏感</td><td>并行度高，调度空转增多</td></tr><tr><td>精度链</td><td>分数块大，重标定次数少</td><td>重标定频繁，统计量开销上升</td></tr></tbody></table>\n<p>落到 Blackwell 的具体机制上，2-SM MMA 与 tcgen05 的组合改变的是单次 MMA 的形状而非分块逻辑本身：一次 MMA 覆盖更大的 N 维，K/V 块的复用次数下降，HBM 读写进一步压缩，但 TMEM 中累加器的驻留与分数块的 SRAM 占用形成新的配比约束；第五代 Tensor Core 的低精度吞吐只有在块尺寸足够大、K/V 复用足够充分时才转化为端到端收益。因此容量规划不能引用论文数字，必须在目标硬件上以 HBM 读写量、片上占用溢出与块调度空转为观测项逐档实测，把块尺寸、精度与批调度三者作为一个联合调参面处理。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-19\">十九 · 显存账本的三个账户与一条硬边界</h3>\n<p>把一次推理的显存占用拆成三本账：权重、激活、KV cache。权重是静态的，随模型参数量与数值精度变化，部署后基本不动；激活是动态的，随批内并发与序列长度波动，峰值出现在预填阶段；KV cache 是随请求生命周期增长的，按 token 逐个追加，是长上下文场景里唯一会随并发数线性叠加的账户。三者的差别不在大小，而在**增长方式**：权重是常数项，激活是峰值项，KV 是斜率项。容量规划的错误几乎都来自把斜率项当常数项算。</p>\n<p>Blackwell 档位的硬边界是 HBM3e 容量。以 GB200 NVL72 的机柜形态为例，单 GPU 侧的 HBM3e 容量与带宽配比决定了三本账能分到多少。工程上不引用论文数字，而是按目标硬件的容量上限做可复算预算：设单卡 HBM 容量为 C，权重占用 W，激活峰值 A，KV 每 token 每层占用 k，层数 L，并发请求数 B，平均上下文长度 S，则可行域是</p>\n<div class=\"formula\">$$W + A + B \\cdot S \\cdot L \\cdot k \\le C \\cdot \\eta$$</div>\n<p>其中 η 是留给碎片、临时缓冲与通信缓冲的安全系数，工程上取小于 1 的值，具体取值需在目标栈上实测碎片率后确定。这个不等式不是估算工具，而是**否决工具**：任何容量规划只要不满足它，后面的吞吐推算全部作废。举例：一个 70B 级模型在 FP8 下权重占用是确定的常数项，若把剩余容量全部分给 KV，则并发上限由 B·S 的乘积直接封顶——此时把批大小翻倍等价于把平均上下文砍半，二者在容量上不可兼得。</p>\n<p>注意 k 的定义：每 token 每层每个 KV 头存 K 与 V 两份，故 k 与头数、头维度、数值精度成正比。NVFP4 或 FP8 存 KV 会把 k 压下来，但压缩比不是免费的，它换来的是精度损失与反量化开销，这笔账要单独记在带宽与数值稳定两栏，不能混进容量栏里假装白赚。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-20\">二十 · 分页：把斜率项从连续数组变成块表</h3>\n<p>KV cache 最朴素的布局是按请求预分配一段连续显存，长度取最大可能上下文。这直接把斜率项变成峰值项：短请求占着长请求的坑，显存利用率被最坏情况绑架。分页的思路是把 KV 切成固定粒度的块（page），请求持有一张块表，块在物理显存里不连续，按需追加。逻辑地址到物理块的映射由块表维护，注意力核在读取 K、V 时按块表跳转。</p>\n<p>伪代码层面的关键循环是：对每个请求的每个逻辑块索引，查表得到物理块号，再在片上拼出该块的 K、V 参与分块注意力计算。这与 FlashAttention 的列块遍历天然对齐——外层遍历 K、V 块，块边界正好落在 page 边界上，在线 softmax 的运行最大值 m 与归一化因子 l 按 Q 块维护，跨 page 合并时只需重标定累加器，不需要回读已处理的 page。</p>\n<p>代价有三处。其一，块表本身占显存，粒度越细表越大，粒度越粗内部碎片越多，粒度选择是表开销与碎片率的折中，需按目标序列长度分布实测。其二，非连续访问破坏 HBM 的突发传输效率，块粒度若小于 HBM 事务粒度，有效带宽下降，长上下文下这个损失会体现在解码阶段的每 token 延迟上。其三，块表查询引入间接寻址，核内循环多了一次索引计算，属于调度开销而非算力开销，在带宽瓶颈场景下可被隐藏，在算力受限场景下则暴露为延迟。</p>\n<p>具体例子：同一张卡上跑两个请求，一个上下文极短、一个上下文极长。连续预分配方案下两者都按最长坑位占显存，并发上限被短请求拖死；分页方案下短请求只占少数几个 page，剩余容量留给长请求追加，并发上限由实际 token 总数而非最坏长度决定。这就是斜率项被真正当作斜率项管理的时刻。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-21\">二十一 · 压缩、复用、卸载：三条不同的省法</h3>\n<p>压缩作用于 k 本身。量化 KV 到 FP8 或 NVFP4 直接缩小 k，容量账立刻改善；代价是反量化要在片上做，且在线 softmax 的数值稳定需要重新评估——运行最大值 m 与归一化因子 l 在低精度累加下的舍入行为与高精度不同，块合并时的重标定误差会累积。工程判断是：KV 量化适合容量吃紧、带宽也吃紧的场景，因为它在省容量的同时省了读带宽；但它不适合对数值极敏感的层，需逐层评估而非全局一刀切。</p>\n<p>复用作用于跨请求的共享前缀。系统提示、few-shot 示例、长文档前缀在多个请求间完全相同，其 KV 块可被多个块表指向同一物理块，引用计数管理生命周期。这在容量上直接把 B·S 里的公共部分从乘数变成加数：N 个请求共享一段长前缀，只付一份显存。代价是写时复制——一旦某请求要修改共享块（例如继续生成），需先复制再写，复制开销出现在首个分歧 token 处，表现为该请求的首 token 延迟尖峰。复用与分页是同一套块表的两种用法，实现上不冲突。</p>\n<p>卸载作用于层级。把冷层或冷请求的 KV 块换出到主机内存甚至远端存储，需要时换回。省的是 HBM 容量，付的是 PCIe 或网络往返带宽与延迟。判断标准很直接：若换出块的复用间隔远大于换入换出的传输时间，卸载划算；若请求的注意力模式会在短时间内反复触及同一批块，卸载就是把带宽瓶颈从 HBM 搬到链路上，得不偿失。卸载粒度应与 page 粒度一致，否则换出换入的元数据开销会吃掉收益。</p>\n<p>三条路径的共同点是都在动 k 或动 B·S，没有一条能绕过第一节的不等式。区别在于代价记在哪一栏：压缩记在数值稳定与反量化算力，复用记在写时复制的延迟尖峰，卸载记在链路带宽。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-22\">二十二 · 带宽瓶颈的位置：预填与解码不是同一道题</h3>\n<p>预填阶段是算力与带宽混合受限：Q 块与 K、V 块做块乘，矩阵乘的算力密度高，分块带来的 HBM 读写下降直接转化为吞吐。解码阶段则几乎纯粹是带宽受限：每生成一个 token，要把全部历史 KV 读一遍，算力只做一次向量-矩阵乘，算术强度极低。这就是为什么长上下文解码的每 token 延迟由 KV 读带宽决定，而非由 tensor core 吞吐决定。</p>\n<p>把这条差异写成可算的量：解码一步需读取的 KV 字节数为 B·S·L·k，若有效带宽为 BW，则该步的 KV 读取时间下界是 B·S·L·k / BW。这个下界与算力无关，任何核优化都无法突破，只能靠减少读取量（压缩、复用、稀疏化）或提高有效带宽（更好的访问局部性、块粒度对齐事务）来改善。分页在这里的作用是双面的：它省容量，但若块粒度过小破坏突发传输，有效带宽下降会直接抬高这个下界。</p>\n<p>具体例子：同一模型、同一并发，上下文翻倍。预填阶段的分块注意力吞吐下降幅度小于线性，因为块乘的算力复用还在；解码阶段的每 token 延迟则近似线性上升，因为读取量线性上升而算力没变。工程上把这两段分开做容量规划，预填看激活峰值与算力配比，解码看 KV 读取下界与带宽配比，混在一起算必然失真。</p>\n<p>Blackwell 的 tcgen05 与 TMEM 改变的是片上累加与矩阵乘的组织方式，它提升的是算力侧与片上复用，对解码阶段的 KV 读取下界没有直接影响。真正影响下界的是 KV 布局、块粒度、量化精度与复用命中率——这四项都属于显存账本的管理范畴，而非算子微架构范畴。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-23\">二十三 · 一个可复算的显存预算</h3>\n<p>把前面的量组织成一张可逐项填写的表，每一项都对应一个可观测或可推导的量，不引入论文未给出的数字。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>构成</th><th>增长方式</th><th>可压缩手段</th><th>代价记在哪</th></tr></thead><tbody>\n<tr><td>权重 W</td><td>参数量 × 每参数字节</td><td>常数</td><td>FP8/NVFP4 量化</td><td>精度、反量化算力</td></tr>\n<tr><td>激活 A</td><td>批内并发 × 序列长度 × 隐藏维 × 精度</td><td>峰值（预填）</td><td>分块降低中间量驻留</td><td>SRAM 容量约束、块调度</td></tr>\n<tr><td>KV 容量</td><td>B·S·L·k</td><td>斜率（随 token 追加）</td><td>分页、量化、复用、卸载</td><td>块表开销、碎片、链路带宽</td></tr>\n<tr><td>运行时缓冲</td><td>通信缓冲、临时 workspace、块表</td><td>随并发与拓扑</td><td>拓扑对齐、粒度调参</td><td>有效容量下降</td></tr>\n</tbody></table>\n<p>复算步骤：先由权重与运行时缓冲确定常数项占用，剩余容量乘以安全系数得到可用动态容量；再由目标并发与平均上下文算出 KV 需求，若超出则依次尝试复用命中（削减公共前缀部分）、KV 量化（缩小 k）、分页细化（降低碎片）、卸载（移出冷块）；每一步都记录它把哪一栏代价抬高。最后用解码阶段的读取下界 B·S·L·k / BW 校验每 token 延迟是否满足 SLO，若不满足，说明容量虽然够但带宽不够，此时应优先考虑复用与量化而非继续加卡。</p>\n<p>这张表的价值在于它把“显存够不够”和“带宽够不够”拆成两个独立判据。工程上常见的错误是容量达标就认为可以上线，结果解码阶段被 KV 读取下界卡住，尾延迟超标。反过来，带宽充裕但容量不足时，卸载与复用是首选，因为它们的代价记在链路与延迟尖峰上，而链路在容量受限场景下往往有余量。</p>\n<p>最后落到一个具体机制上：分页块表的粒度选择应当与 HBM 事务粒度和 FlashAttention 的 K、V 列块边界同时对齐。三者对齐时，块表跳转不破坏突发传输，列块遍历不跨页断裂，在线 softmax 的重标定不因页边界而额外回读；三者错位时，容量账虽然算得平，有效带宽却被间接寻址与碎片吃掉，解码阶段的每 token 延迟下界被实际抬高。这个对齐关系是容量规划与算子实现之间的接口，也是本部分唯一不能靠调参绕过的硬约束。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-24\">二十四 · 分块注意力的边界：SRAM 配额、线性账本与失效条件</h3>\n<p>FlashAttention 的显存收益不是“免费”的，它把 O(N²) 的注意力矩阵从 HBM 账本上抹掉，代价是把压力转移到片上 SRAM 的驻留配额。前向每个 Q 行块需要同时容纳该块的 Q 分片、当前 K/V 列块分片、局部分数块、运行最大值 m、归一化因子 l 与指数加权 V 累加器；块尺寸 B<sub>r</sub>×B<sub>c</sub> 一旦超过 SRAM 可用容量，核函数要么溢出到本地内存（延迟陡增），要么被迫缩小块，导致 K/V 块的数据复用率下降、HBM 读放大。可复算的约束是：<div class=\"formula\">$$B_r B_c\\,(d_{\\text{head}}\\cdot s + s) + B_r\\,(d_{\\text{head}}\\cdot s + 2s)\\ \\le\\ C_{\\text{SRAM}}$$</div>其中 s 为元素字节数（FP8 为 1、BF16 为 2），d<sub>head</sub> 为头维，C<sub>SRAM</sub> 为该 SM 可支配的片上容量。这个不等式解释了为什么同一份核在 B200 与 GB200 的不同 SM 配置上必须逐档调参，而不能照搬论文块尺寸。</p>\n<p>把账本从平方级换成线性级后，推理侧的显存预算结构也随之改写。以单层单头为例，KV cache 的字节数为 <div class=\"formula\">$$\\text{KV bytes}=2\\times L\\times H_{kv}\\times d_{\\text{head}}\\times N\\times s$$</div>其中 L 为层数、H<sub>kv</sub> 为 KV 头数、N 为已缓存 token 数。注意这里 N 是线性项，与 FlashAttention 反向“保存输出与 softmax 统计量、按块重算”的线性化方向一致：两者都把序列维度的平方项消掉，但 KV cache 的线性项在长上下文解码时仍会压满 HBM3e 容量。工程判断是：当 2LH<sub>kv</sub>d<sub>head</sub>s 乘以目标并发与上下文长度后逼近单卡 HBM3e 可用容量，就必须引入分页（按块粒度分配、消除变长填充浪费）、量化（FP8/NVFP4 压缩 KV 字节）或卸载（把冷 KV 换出到主机侧），而这些机制与分块算子正交，组合时需重新核算 SRAM 占用——分页粒度越细，块调度空转越多。</p>\n<p>失效条件集中在三处。其一，短序列：N 小到注意力矩阵本可整块驻留时，分块的在线 softmax 重标定与核内循环调度开销超过 HBM 读写节省，端到端延迟不降反升，这是“把分块收益当无条件加速”的典型误判。其二，算力受限而非带宽受限：当目标档位的 HBM 带宽相对算力并不紧张，重计算多出的那次前向块计算直接体现为反向墙钟时间，收益被抵消。其三，变长批：批内序列长度不齐时按最长序列分块，短请求承担填充浪费，Q 块并行度被最长序列拖住，尾延迟对带宽瓶颈更敏感。因此容量规划不能引用论文数字，必须在目标硬件上实测 HBM 读写量、片上占用溢出与块调度空转三项指标，再决定块尺寸与是否启用重计算路径。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>序列维度阶</th><th>主要压力点</th></tr></thead><tbody><tr><td>完整注意力矩阵（标准实现）</td><td>O(N²)</td><td>HBM 容量与读写带宽</td></tr><tr><td>FlashAttention 中间量</td><td>O(N)（输出+统计量）</td><td>SRAM 驻留配额、重算算力</td></tr><tr><td>KV cache</td><td>O(N)（随并发线性放大）</td><td>HBM3e 容量、分页碎片</td></tr></tbody></table>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-25\">二十五 · 从算子分块到请求分块：调度层的块边界</h3>\n<p>FlashAttention 在算子内部把 Q 切成行块、K/V 切成列块，块尺寸由片上 SRAM 容量决定；这个约束在调度层会以另一种形式复现——连续批处理（continuous batching）在每一步解码时把新到达的请求插入正在运行的批，批内序列长度参差，于是“块”从 SRAM 分块变成了请求分块。两者的共同点是：块边界一旦选定，就同时决定了并行度、片上驻留压力与 HBM 读写比例。算子层块过小则复用率下降，调度层批过小则 GPU 空转、批过大则 KV cache 驻留压力上升。工程上必须把这两个尺度放在同一张表里调：给定 SRAM 容量与 HBM 带宽比，先定算子块尺寸，再由 KV cache 显存预算反推最大并发批，最后由 SLO 反推可接受的排队深度。</p>\n<p>连续批处理的核心机制是迭代级调度：每个 decode step 结束后，完成的请求退出、排队的请求进入，批组成在 token 粒度上变化。这与 FlashAttention 前向“外层遍历 K/V 块、内层遍历 Q 块”的双层循环结构同构——批内每个请求相当于一个 Q 行块，KV cache 相当于不断增长的 K/V 列块。代价是明显的：批组成每步变化，导致核内循环的块数不稳定，片上累加器与运行统计量的生命周期被打断，编译期难以做静态展开；同时变长批需要按最长序列填充，填充部分照样占用 SRAM 与带宽。</p>\n<p>具体例子：一个在线服务同时收到短问答（几十 token）与长文档摘要（数万 token）请求。若按请求级批处理，短请求必须等长请求跑完才能返回，首 token 延迟被长请求绑架；改用迭代级连续批处理后，短请求在长请求的 decode 间隙插入，代价是每个 step 的批内序列长度方差变大，KV cache 分页粒度必须足够细才能避免显存碎片。分页粒度越细，页表间接寻址的带宽开销越高，这与算子层块过小导致复用率下降是同一类权衡。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-26\">二十六 · Chunked prefill：把预填的平方级压力摊平</h3>\n<p>预填阶段一次处理整段 prompt，注意力计算量随 prompt 长度增长，若与 decode 请求混批，长 prompt 的预填会占满 SM 与带宽，把同批 decode 请求的 token 间隔（inter-token latency）拉长，尾延迟直接恶化。chunked prefill 把长 prompt 切成若干 chunk，每个调度周期只处理一个 chunk，与 decode 请求拼成同一批。这样每个 step 的计算量被钳制在固定上限，decode 的 token 间隔抖动被压住。</p>\n<p>chunk 尺寸的选择直接对应 FlashAttention 的块尺寸约束：chunk 太大，单 step 内 Q 块数多、KV 列块遍历长，片上驻留与寄存器压力上升；chunk 太小，调度开销与核启动开销占比上升，且 chunk 之间的在线 softmax 统计量必须跨 step 保存——这正好复用了 FlashAttention 前向保存运行最大值 m 与归一化因子 l 的做法，把跨 chunk 的 softmax 合并变成一次状态传递而非重算。</p>\n<div class=\"formula\">$$\\text{step cost} \\approx \\underbrace{c_{\\text{prefill}}(L_{\\text{chunk}})}_{\\text{chunk 预填}} + \\underbrace{c_{\\text{decode}}(B_{\\text{dec}})}_{\\text{同批解码}},\\quad L_{\\text{chunk}} \\le L_{\\max}^{\\text{SRAM}}$$</div>\n<p>代价在于：chunk 化使预填的总 step 数增加，端到端首 token 延迟（TTFT）对超长 prompt 反而变长，因为最后一个 chunk 要等前面所有 chunk 排完。这是一个明确的取舍——用 TTFT 换 decode 的尾延迟稳定性。容量规划上，若 SLO 同时约束 TTFT 与 token 间隔，就必须为长 prompt 预留独立的预填通道，而不是把所有请求塞进同一条 chunk 流水线。</p>\n<p>具体例子：批内有一个 32k token 的 prompt 与 16 个 decode 请求。不分 chunk 时，该 step 的预填独占带宽，16 个 decode 请求的 token 间隔出现尖峰；切成固定大小 chunk 后，每 step 预填计算量被钳制，decode 请求的间隔方差收敛，代价是该 prompt 的 TTFT 增加若干个 step 的排队时间。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-27\">二十七 · 优先级与抢占：显存不足时的调度决策</h3>\n<p>连续批处理把并发推高后，KV cache 显存成为硬约束。当新请求到达而 KV cache 池无空闲页时，调度器必须在三种动作中选择：排队等待、拒绝、抢占（preemption）已在运行的请求。抢占的机制是把被抢占请求的 KV 页换出到主机内存或直接丢弃、之后靠重算恢复。重算恢复的代价与 FlashAttention 反向重计算同源——都是“以算力换显存”，区别在于推理侧重算的是整段前缀的 KV，而非单个注意力块的中间量。</p>\n<p>抢占策略的工程判断点在于：换出到主机内存的代价是 PCIe 带宽往返，重算的代价是重新跑一遍预填。对于长前缀请求，重算成本随前缀长度线性增长且占用 SM，会挤占其他请求的算力；换出则占用 PCIe 带宽但不占 SM。选择哪条路径取决于当前瓶颈是算力还是互联带宽——这与 FlashAttention 收益依赖带宽瓶颈程度是同一个判断逻辑：带宽紧张时重算更划算，算力紧张时换出更划算。</p>\n<ul>\n<li>优先级维度：按 SLO 剩余预算排序，而非按到达顺序；剩余预算小的请求优先，避免其在排队中违约。</li>\n<li>抢占粒度：按请求整体抢占还是按页抢占；按页抢占可实现部分换出，但页表管理开销上升。</li>\n<li>恢复策略：重算前缀需重新走 chunked prefill 路径，因此抢占决策必须与 chunk 尺寸联动，否则恢复时的单 step 计算量再次失控。</li>\n</ul>\n<p>具体例子：KV cache 池满时，一个已运行的长文档请求与若干短问答请求竞争。若按到达顺序，长请求占着大量页不放，短请求全部排队；若按剩余预算抢占，长请求被换出部分页，短请求得以插入，长请求在预算耗尽前恢复。代价是长请求的端到端延迟方差变大，尾延迟指标必须以分位数而非均值来考核。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-28\">二十八 · 分离式预填/解码：把两种负载放到不同资源池</h3>\n<p>预填是计算密集、批内并行度高、对带宽相对不敏感；解码是访存密集、批内并行度低、每 token 都要读一遍 KV cache。把两者混在同一批里，硬件配置只能取折中。分离式（disaggregated）预填/解码把预填池与解码池物理分开，中间通过 KV cache 传输衔接：预填池算完一段前缀，把 KV 页经互联传给解码池，解码池只做自回归。</p>\n<p>这个架构的代价集中在 KV 传输上：传输量与前缀长度、层数、头数成正比，传输带宽成为新的瓶颈。NVLink 域内传输与跨节点传输的代价差一个量级，因此分离式部署的拓扑选择直接决定收益。工程上要回答的问题是：预填池与解码池的配比。配比由两个量决定——单位时间到达的 prompt token 总量与 decode 池的 token 生成速率，前者决定预填池规模，后者决定解码池规模。</p>\n<div class=\"formula\">$$N_{\\text{prefill}} : N_{\\text{decode}} \\approx \\frac{\\text{prompt token 到达率} \\times \\text{每 token 预填算力}}{\\text{decode 池 token 生成率} \\times \\text{每 token 解码算力}}$$</div>\n<p>与 FlashAttention 分块思想的衔接点在于 KV 页的布局：预填池按块计算出的 KV 必须以解码池能直接分页读取的形式落盘，页粒度要与算子块尺寸对齐，否则解码侧的块遍历会出现跨页碎片，HBM 读写比例回升。这也是为什么分离式架构不能简单照搬单机部署的块尺寸——两侧的 SRAM 容量与带宽配比不同，块尺寸需分别实测。</p>\n<p>具体例子：一个服务把预填与解码分到两组 GPU，预填池按 chunked prefill 处理长 prompt，解码池维持大并发连续批处理。若 KV 传输走跨节点链路，传输延迟会叠加到 TTFT 上；若预填与解码同处一个 NVLink 域，传输开销被压到可接受范围，但资源池的隔离性下降，预填尖峰仍可能通过共享互联影响解码。这是一个拓扑与隔离度的取舍，不是单纯的软件配置问题。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-29\">二十九 · 尾延迟怎么压：从均值指标到分位数约束</h3>\n<p>时延与吞吐的取舍在调度层表现为一条曲线：并发越高，吞吐越高，但排队深度增加使尾延迟（p99 token 间隔、p99 TTFT）恶化。压尾延迟的手段不是提高平均吞吐，而是消除造成尖峰的离散事件——长 prompt 预填、批组成突变、KV 池满触发的抢占、跨池 KV 传输抖动。每类事件都对应一个可钳制的机制：chunked prefill 钳制预填计算量，迭代级调度钳制批组成变化幅度，预留 KV 页水位线避免池满抢占，分离式部署把预填尖峰隔离到独立资源池。</p>\n<p>分位数约束下的容量规划与均值约束完全不同：均值约束只需满足平均负载，分位数约束要求系统在负载方差的高分位处仍不违约，因此必须为方差预留余量。余量的来源是调度器的排队模型——给定到达率与服务率的方差，排队深度分布决定 p99 等待时间。工程判断是：当负载方差主要来自 prompt 长度分布时，优先用 chunked prefill 削峰；当方差来自到达率突发时，优先用优先级与预留水位线；两者叠加时，分离式部署是唯一能把两类方差解耦的手段。</p>\n<p>具体例子：一个服务的 p99 TTFT 超标，均值正常。排查发现超标请求全部是长 prompt，且集中在到达突发的时段。把长 prompt 路由到独立预填池并启用 chunked prefill 后，p99 TTFT 的尖峰被削平，代价是这部分请求的均值 TTFT 上升、预填池利用率下降。这就是尾延迟优化的典型账本：用均值与利用率换分位数。</p>\n<p>最后落到一个具体机制上：调度器的块尺寸、chunk 尺寸、KV 页粒度三者必须与算子层 FlashAttention 的 SRAM 分块尺寸联合标定。任何一层的块边界与其余两层不匹配，都会在 HBM 读写比例上留下可观测的回升——这是判断调度配置是否与算子配置对齐的工程信号，也是容量规划时不能直接引用论文数字、必须在目标硬件上逐档实测的原因。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-30\">三十 · 分块算子的调度边界：连续批处理与 chunked prefill 下的块尺寸、抢占与尾延迟</h3>\n<p>FlashAttention 的分块尺寸由片上 SRAM 容量决定，这一约束在调度层会被放大：连续批处理把不同长度的请求拼进同一迭代，若批内序列长度不齐，Q 块并行度按最长序列对齐，短请求的块被填充浪费，SRAM 驻留块数上升。chunked prefill 把长预填切成若干 chunk 与解码请求混跑，每个 chunk 仍要按块遍历 K、V 列块，HBM 读写量随 chunk 数线性累加而非一次性摊薄；此时单次迭代的片上占用由 chunk 内 Q 块数乘以驻留 K、V 块数决定，超过 SRAM 预算就触发溢出或被迫缩小块尺寸，复用率下降。系统代价体现在尾延迟：长预填 chunk 与解码请求共享同一 SM 周期，解码请求的 token 间隔被拉长，P99 首 token 延迟随 chunk 长度与批内长请求占比上升。工程判断是给 chunk 长度设上限并与块尺寸联合调参，而不是把 chunk 当作独立旋钮。</p>\n<p>优先级与抢占在分块算子下代价不对称。抢占一个正在遍历 K、V 块的预填请求，已累加的运行最大值 m 与归一化因子 l 必须随请求状态换出到 HBM，恢复时重新载入并继续块循环；若抢占发生在块循环中段，重算的块数取决于检查点粒度。用 <span class=\"formula\">$$T_{\\text{preempt}} \\approx \\frac{B_{\\text{state}}}{BW_{\\text{HBM}}} + n_{\\text{recompute}} \\cdot t_{\\text{block}}$$</span> 描述，状态换出带宽与重算块数是两项独立开销，块尺寸越大单块重算越贵但块数越少，存在与 SRAM 容量绑定的最优点。解码请求被抢占的代价远低于预填，因为其 KV 分页状态可原地保留，故调度器应优先抢占预填而非解码，把抢占预算留给长 chunk。</p>\n<p>分离式预填/解码把这两类负载拆到不同实例，分块算子的收益结构随之改变：预填侧序列长、带宽瓶颈显著，分块收益最大；解码侧每步只处理单 token，Q 块极小，块循环退化为对 KV cache 的逐块读取，收益主要来自 KV 分页与块对齐而非 Q 分块。跨实例传输 KV 时，块边界需与传输粒度对齐，否则出现部分块重传。下表对比三种调度形态下分块算子的主要代价来源。</p>\n<table class=\"mini\"><thead><tr><th>调度形态</th><th>主要代价</th><th>失效条件</th></tr></thead><tbody><tr><td>连续批处理</td><td>批内长度不齐导致填充与 SRAM 驻留上升</td><td>短请求占比高、块并行度不足</td></tr><tr><td>chunked prefill</td><td>chunk 数线性累加 HBM 读写，解码间隔被拉长</td><td>chunk 过长、批内长请求集中</td></tr><tr><td>分离式预填/解码</td><td>KV 传输与块边界对齐开销</td><td>块粒度与传输粒度不匹配</td></tr></tbody></table>\n<p>尾延迟的压制落在块调度而非算子内部：把长预填的块循环切成可抢占的检查点，使抢占重算块数有上界；对解码请求保留独立的高优先级通道，避免其与预填 chunk 争用同一 SRAM 预算；块尺寸按硬件档位逐档实测，不以论文数字直接做容量规划。分块算子与批调度正交，但组合后的 SRAM 占用必须重新核算，这是调度层不能回避的约束。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-31\">三十一 · 切分维度与通信原语的对应关系</h3>\n<p>把 FlashAttention 的分块算子放到多卡拓扑上，第一个要回答的问题不是“用几张卡”，而是“切哪一维、切完之后哪条通信原语被激活”。张量并行（TP）切的是权重矩阵的列或行，每层注意力的 QKV 投影被拆到不同 rank，前向需要一次 All-Reduce 把各 rank 的部分和归并；流水并行（PP）切的是层，激活值在 stage 边界做点对点发送，通信量正比于 batch×hidden×序列长度；数据并行（DP）切的是请求，梯度侧是 All-Reduce，推理侧只在权重同步时通信；专家并行（EP）切的是 MoE 的专家，token 需要被路由到持有目标专家的 rank，走 All-to-All。这四种切分对通信的敏感度完全不同：TP 是每层都同步、延迟敏感；PP 是流水气泡敏感；EP 是带宽敏感且流量不规则；DP 在纯推理下几乎不产生稳态通信。</p>\n<p>FlashAttention 的分块结构在这里给出一个具体约束：Q 行块与 K、V 列块的划分必须与切分边界对齐。若采用序列并行把一条长序列的 K、V 列块分散到多个 rank，每个 rank 只持有部分 K、V 块，那么在线 softmax 的合并就变成跨 rank 归约问题。设 rank r 持有 K、V 的第 r 段列块，各自算出局部运行最大值 $m_i^{(r)}$ 与局部归一化因子 $\\ell_i^{(r)}$，全局合并必须满足</p>\n<div class=\"formula\">$$m_i=\\max_r m_i^{(r)},\\qquad \\ell_i=\\sum_r \\ell_i^{(r)}\\exp\\!\\left(m_i^{(r)}-m_i\\right),\\qquad \\text{out}_i=\\frac{\\sum_r \\ell_i^{(r)}\\exp(m_i^{(r)}-m_i)\\,\\text{out}_i^{(r)}}{\\ell_i}$$</div>\n<p>这个式子说明：序列并行下的注意力不是简单把输出拼起来，而是要把每个 rank 的 $(m_i^{(r)},\\ell_i^{(r)},\\text{out}_i^{(r)})$ 三元组做一次带重标定的归约。归约量是 $O(N\\cdot d)$ 级别的输出加两个标量，比把完整注意力矩阵跨卡搬运便宜得多，但归约点出现在每一层、每一个 Q 块上，延迟叠加不可忽略。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-32\">三十二 · NVLink 5 与 NVSwitch：把 All-Reduce 压到可接受区间</h3>\n<p>Blackwell 档位的 GB200/GB300 NVL72 用 NVLink 5 与 NVSwitch 把单机架内的 72 个 GPU 连成统一域，机架内任意两卡之间的通信不经过 InfiniBand，走的是交换芯片的直连路径。对 TP 而言这是决定性的：TP 组越大，每层 All-Reduce 的参与方越多，环形或树形归约的跳数上升，而 NVSwitch 的全连接拓扑把“跳数”从链路的串联变成交换级的一跳转发，归约延迟不再随组规模线性增长。工程判断上，TP 组的规模应当被限制在 NVLink 域内，跨域做 TP 会把每层同步的延迟从微秒级推到几十微秒级，直接吃掉分块算子省下来的带宽收益。</p>\n<p>代价要算清楚。以一层注意力的 TP 为例，All-Reduce 的数据量约为 $2\\times b\\times s\\times d\\times$（字节数取决于精度），若用 FP8 则减半。设单次 All-Reduce 的有效带宽为 $B_{\\text{ar}}$，则该层通信时间为 $T_{\\text{ar}}=2bsd/B_{\\text{ar}}$，而该层分块注意力的计算时间为 $T_{\\text{comp}}$。通信是否成为瓶颈，取决于比值 $T_{\\text{ar}}/T_{\\text{comp}}$：当序列长度 $s$ 增长时，$T_{\\text{comp}}$ 随 $s$ 线性增长（分块后 HBM 读写与 $s$ 线性相关），$T_{\\text{ar}}$ 也随 $s$ 线性增长，两者同阶，因此长序列并不会自动稀释 TP 通信占比；真正稀释它的是增大 batch 或提高单卡算力利用率。这就是为什么在 NVL72 上做长上下文推理时，TP 组规模与 batch 需要联合调，而不能只按显存容量反推 TP 大小。</p>\n<p>具体例子：一个 72 卡 NVL72 机架部署千亿级 MoE 模型，注意力层用 TP=8、MoE 层用 EP=64。注意力层的 All-Reduce 落在 8 卡 NVLink 域内，每层同步延迟被交换芯片压住；MoE 层的 All-to-All 横跨 64 卡，token 路由的流量不规则，尾延迟由最拥挤的那条链路决定。两类通信的瓶颈性质不同，监控指标也必须分开看。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-33\">三十三 · All-to-All 的不规则性：EP 是通信瓶颈的高发区</h3>\n<p>EP 的 All-to-All 与 TP 的 All-Reduce 在流量形态上完全不同。All-Reduce 是规整的、所有 rank 等量的归约；All-to-All 是每个 rank 向其余所有 rank 发送不同大小的数据，token 按专家路由分布，热专家会集中到少数 rank。分块注意力在这里的角色是间接的：它决定了单次前向中 token 的驻留时间与 batch 形态，从而影响 All-to-All 的批处理窗口。若分块算子把每层的激活写回 HBM 的时机打散，All-to-All 的发送缓冲就更难凑成大块，小包传输的协议开销占比上升。</p>\n<p>量化代价的方式是看 All-to-All 的有效吞吐与链路峰值之比。设每个 token 需要发给 $k$ 个专家（top-k 路由），单 token 负载为 $d$ 字节，batch 内 $n$ 个 token，则单次 All-to-All 的发送量为 $n\\cdot k\\cdot d$，分摊到 $P$ 个 rank 上每 rank 平均发送 $nkd/P$，但实际分布由路由决定，最热 rank 的发送量可达均值的数倍。工程上要观测的是 P99 而非均值：尾部的拥塞 rank 决定了整个 MoE 层的完成时间。缓解手段是容量因子（capacity factor）限制每专家接收的 token 数，代价是溢出 token 被丢弃或走残差路径，影响模型质量，这个取舍必须在推理侧显式配置而非默认放开。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-34\">三十四 · NIXL 传输：把 KV 搬移从计算路径上剥离</h3>\n<p>分离式预填/解码与 KV cache 跨节点复用的场景里，KV 的搬移量与注意力计算量是解耦的。NIXL 作为传输层的作用是把 KV 块的搬运做成异步的、可被计算流掩盖的后台操作，而不是让解码 rank 阻塞等待。对 FlashAttention 的分块布局而言，这意味着 KV cache 的分页粒度必须与分块尺寸兼容：若 KV 按页存储、页大小与 K、V 列块尺寸不整除，搬运后仍需在片上做重排，等于把省下来的 HBM 带宽又花回去。</p>\n<p>代价模型可以写成：设单次解码步需要搬移的 KV 量为 $S_{\\text{kv}}$ 字节，传输链路有效带宽为 $B_{\\text{nixl}}$，则搬移时间为 $S_{\\text{kv}}/B_{\\text{nixl}}$；该步的计算时间为 $T_{\\text{dec}}$。当 $S_{\\text{kv}}/B_{\\text{nixl}}&gt;T_{\\text{dec}}$ 时，KV 传输成为解码步的瓶颈，此时增加解码 batch 并不能提升吞吐，反而加剧链路争用。判断阈值的方法是实测单步解码时间与 KV 搬移时间的比值，比值接近 1 就说明已经踩到传输瓶颈，需要改用更近的存储层级（同机架 NVLink 域内的 KV 池）或压缩 KV 精度。</p>\n<p>具体例子：预填节点与解码节点分离部署，预填侧按分块算子算出 KV 并写入本地池，NIXL 把 KV 块异步推送到解码侧的池。若解码侧 batch 内序列长度差异大，短序列先完成、长序列仍在等 KV，传输的尾延迟直接体现为首 token 之后的间隔抖动。这类抖动在 SLO 上表现为 TPOT 的 P99 抬升，而不是均值变化，容量规划必须按 P99 留余量。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-35\">三十五 · 通信何时成为瓶颈：三个可判定的信号</h3>\n<p>第一个信号是计算通信比。对任意一层，定义 $\\rho=T_{\\text{comm}}/T_{\\text{comp}}$，$\\rho$ 随并行组规模、序列长度、精度变化。TP 组从 8 扩到 16 时，All-Reduce 参与方翻倍，$\\rho$ 上升；若同时把精度从 FP16 降到 FP8，通信量减半，$\\rho$ 回落。工程上应把 $\\rho$ 作为并行配置的选型指标，而不是先定卡数再补通信优化。</p>\n<p>第二个信号是链路利用率的分位分布。规整的 All-Reduce 看均值即可，All-to-All 必须看 P99。当 P99 利用率逼近链路峰值而均值仍有余量时，说明瓶颈在路由不均而非总带宽不足，扩容无效，应改路由策略或容量因子。</p>\n<p>第三个信号是分块算子的 SRAM 占用与通信缓冲的争用。分块尺寸受 SRAM 容量硬约束，块越大复用率越高但驻留压力越大；当同一 SM 上还要为通信缓冲留出片上空间时，块尺寸被迫缩小，复用率下降，HBM 读写回升。这个耦合在 NVFP4/FP8 量化后更敏感，因为低精度下同样的字节数对应更多元素，缓冲的元素计数上升。判断方法是逐档实测块尺寸与通信缓冲的联合占用，而不是照搬单卡调好的块参数。</p>\n<p>最后落在工程判断上：在 Blackwell 档位上，注意力分块算子省下的是 HBM 带宽，而多卡并行引入的是链路带宽与延迟；两者不是同一类资源，不能互相抵消。把 TP 限制在 NVLink 域内、把 EP 的尾延迟按 P99 监控、把 KV 搬移交给 NIXL 异步化并对齐分页粒度，这三条是让分块收益不被通信吃掉的必要条件；任何一条失配，端到端吞吐都会停在链路瓶颈上，而算子本身仍然“正确且高效”。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-36\">三十六 · 当分块注意力遇上多卡切分：通信成为瓶颈的边界</h3>\n<p>FlashAttention 的 IO 感知分块把单卡内的 HBM 读写压到与序列长度线性相关，但它对并行拓扑提出了一个隐性约束：分块边界必须与切分维度对齐，否则片上 SRAM 里精心维护的运行最大值 m 与归一化因子 l 会在跨卡归约时被迫物化。以张量并行（TP）为例，注意力头按 head 维切分时，每个 rank 独立完成自己那组头的在线 softmax，前向无需通信，代价只是每卡 Q、K、V 的块尺寸按 head 数缩小、SRAM 复用率下降；而序列并行（SP）沿序列维切分 K、V 块时，每个 Q 块需要在所有 rank 上遍历完整的 K、V，此时每层每个 Q 块都要做一次 All-Reduce 合并局部 (m, l) 与加权 V 累加器，通信量正比于 Q 块数与隐藏维，与序列长度线性相关。设序列并行度为 $P_s$、每卡 Q 块数为 $B_q$、隐藏维 $d$，单层注意力前向的跨卡归约字节数近似为 $2 B_q P_s d \\cdot \\text{sizeof(dtype)}$，当 $d$ 较大（如 8192）且块数多时，这部分流量会与块内矩阵乘的算力时间同量级，分块带来的带宽收益被通信吃掉。</p>\n<p>解码阶段的切分代价结构完全不同。TP 在解码时每层需两次 All-Reduce（注意力输出与 MLP 输出），单 token 的通信量固定为 $2 \\times 2 \\times d \\times \\text{sizeof(dtype)}$ 字节，但此时算力利用率极低、每 token 的计算时间被 KV cache 读取主导，All-Reduce 的固定延迟反而成为尾延迟主项；NVLink 5 与 NVSwitch 把单跳带宽抬到新档位，使 TP=8 以内的 All-Reduce 在带宽上不再是硬约束，真正的代价转移到集合通信的启动延迟与同步点——每层两个同步点意味着解码步进的流水被切碎，连续批处理下不同请求的 token 步进难以错峰。专家并行（EP）的 All-to-All 则是另一类：MoE 层每个 token 要按路由结果发往不同 rank，All-to-All 的流量正比于 token 数乘以专家隐藏维，且是细粒度、非规则的，NIXL 这类传输层在此处的价值是把 KV cache 与专家权重的跨节点搬运从集合通信语义中解耦出来，用点对点 RDMA 传输替代全局同步，代价是需要显式的内存注册与传输描述符管理，失败时表现为传输队列拥塞而非集合通信超时。</p>\n<p>流水并行（PP）与数据并行（DP）在推理侧的边界更清晰：PP 把层切成阶段，阶段间只传激活，通信量小但引入流水气泡，气泡大小正比于阶段数与微批数之比，解码时微批小、气泡占比高，通常只在跨节点、单卡放不下模型时使用；DP 在推理中主要用于副本扩容，梯度 All-Reduce 不参与前向，因此不构成前向瓶颈，但 KV cache 的副本一致性在分离式预填/解码架构下需要 NIXL 做显式传输，预填节点与解码节点之间的 KV 搬运量正比于序列长度乘以层数乘以 KV 头维，这条链路一旦跨节点，其带宽就成为长上下文首 token 之后稳态吞吐的上界。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>前向通信形态</th><th>与分块的对齐关系</th><th>主要代价</th></tr></thead><tbody><tr><td>TP（head 维）</td><td>每层 All-Reduce 输出</td><td>各 rank 独立在线 softmax，无需合并 m/l</td><td>块尺寸缩小、SRAM 复用率下降；解码同步点增多</td></tr><tr><td>SP（序列维）</td><td>每 Q 块 All-Reduce (m,l) 与累加器</td><td>必须对齐块边界，否则物化局部分数</td><td>通信量正比于块数×隐藏维</td></tr><tr><td>EP（专家）</td><td>All-to-All，细粒度非规则</td><td>与注意力分块正交，但共享 SRAM 预算</td><td>传输队列拥塞、NIXL 描述符管理开销</td></tr><tr><td>PP（层）</td><td>阶段间点对点激活</td><td>无直接关系</td><td>流水气泡，解码小批下占比高</td></tr></tbody></table>\n<p>判断通信是否成为瓶颈，工程上不看拓扑图而看两个比值：一是单层注意力块内计算时间与跨卡归约时间之比，当归约时间超过块乘时间的某个比例时，增加并行度不再缩短端到端延迟；二是 KV 传输带宽与目标 token 速率的乘积是否超过链路可用带宽，在分离式架构下这条判据直接决定预填与解码节点的配比。分块算子本身不改变数学结果，因此它与量化的误差、与 KV cache 分页的粒度可以独立评估，但一旦叠加序列并行，在线 softmax 的合并顺序会改变浮点累加次序，数值稳定性需在目标拓扑上重新验证，而不能沿用单卡调好的块尺寸。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-37\">三十七 · 精度塌陷：在线 softmax 的数值边界与量化叠加</h3>\n<p>FlashAttention 的在线 softmax 在数学上与整块计算等价，但等价性建立在浮点运算的有限精度之上。分块合并的核心是运行最大值 m 与运行归一化因子 l 的递推：新块到达时先用新最大值重标定已累加的分子项，再累加当前块的指数加权 V。重标定因子为 <span class=\"formula-inline\">$$\\exp(m_{\\text{old}}-m_{\\text{new}})$$</span>，当新块的最大分数显著高于旧块时，该因子趋近于零，旧累加项被压到极小量级；反之当 m 几乎不变时，因子接近 1，重标定近乎无操作。问题出现在两个极端：若某 Q 块的分数分布跨块差异极大，旧累加项在重标定后落入低精度尾数区，有效位被截断，输出出现可见偏差；若分数整体偏大且块间最大值频繁刷新，每次重标定都引入一次舍入，误差随块数累积。</p>\n<p>推理侧的精度塌陷通常不是算子本身引起，而是量化与分块叠加。NVFP4/FP8 量化改变块内累加精度，在线 softmax 的指数运算对输入缩放敏感：量化把分数压到更窄的动态范围后，m 与 l 的递推仍按原精度执行，但分子项的量化误差在重标定时被放大。诊断方法是分层剥离：先固定块尺寸与序列长度，关闭量化跑一遍，确认输出与整块参考实现的逐元素误差；再开启量化，观察误差是否随块数线性增长。若误差随块数增长，问题在重标定路径；若误差与块数无关但整体偏移，问题在量化缩放因子。回滚手段是把该层的量化档位降一级，或对分数累加器保留更高精度、仅对 V 的加权累加做低精度。</p>\n<p>工程代价体现在显存与带宽的取舍上：保留高精度累加器意味着片上 SRAM 中每个 Q 块的累加缓冲变大，可同时驻留的块数下降，长序列下的并行度被压缩，尾延迟上升。一个具体例子是长上下文预填阶段，序列被切成大量 K、V 列块，若累加器精度提高一档，单块 SRAM 占用增加，核内循环被迫减小块尺寸，HBM 读写次数上升，吞吐反而下降。这类塌陷不会抛异常，只会让输出质量缓慢劣化，必须靠逐层误差监控捕获。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-38\">三十八 · OOM 与 SRAM 溢出：块尺寸的硬约束</h3>\n<p>OOM 在 FlashAttention 部署中有两个来源，必须分开定位。第一类是 HBM 侧 OOM：分块算子本身不物化完整注意力矩阵，HBM 只读写 Q、K、V、O 与 softmax 统计量，显存占用随序列长度线性增长；但推理系统在算子之外还持有 KV cache、批内多请求的中间缓冲与框架自身的 workspace。当批调度把过多长序列请求塞进同一批，KV cache 与激活值叠加会触发 HBM OOM。第二类是片上 SRAM 溢出：块尺寸按 SRAM 容量选定，块过大无法驻留，表现为核函数启动失败或占用溢出后的静默降级。</p>\n<p>定位 SRAM 溢出的关键是区分“编译期拒绝”与“运行期降级”。前者在核函数加载时即报错，块尺寸与硬件档位不匹配；后者更隐蔽，驱动或运行时在占用超限时降低驻留块数或改变调度，算子仍能跑完但复用率下降。监控应观测片上占用与块调度空转：若同一序列长度下 HBM 读写量突然上升而算力利用率不变，说明块尺寸被压低、数据复用变差。公式上，单块 SRAM 需求近似为 <span class=\"formula-inline\">$$S_{\\text{blk}} \\approx B_q B_{kv}\\,(d_{\\text{head}} + c_{\\text{acc}})$$</span>，其中 B_q、B_{kv} 为 Q 行块与 K、V 列块尺寸，d_head 为头维度，c_acc 为累加与统计量的每元素开销。块尺寸翻倍使 SRAM 需求按平方增长，这是硬约束而非软调参。</p>\n<p>回滚路径按代价排序：先降批内并发，减少同时驻留的块数；再降块尺寸，接受复用率下降；最后降序列长度上限或改走分页 KV cache 的细粒度布局。具体例子是 GB200 NVL72 档位上多请求并发预填，若把块尺寸照搬自另一硬件档位，SRAM 与带宽配比不同，直接出现占用溢出，端到端吞吐下降而单请求延迟不变，这类症状指向片上约束而非 HBM 容量。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-39\">三十九 · 批抖动与尾延迟：变长批的分块失配</h3>\n<p>批抖动来自批内序列长度不齐。分块算子按最长序列分块，短请求被填充到最长长度，填充部分参与块乘但不产生有效输出，算力与带宽被浪费。更严重的是尾延迟：一个长序列请求进入批后，整批的完成时间被它拉长，短请求的 SLO 被拖累。在线 softmax 的块循环次数与序列长度成正比，长序列请求的块数远多于短请求，核内循环在批维度上无法完全并行，调度器只能等待最长块链完成。</p>\n<p>诊断批抖动需要两个观测量：批内序列长度的分布与每批的实际块循环次数。若块循环次数的方差远大于序列长度方差，说明填充浪费被放大；若尾延迟集中在少数批上，检查这些批是否混入了超长请求。伪代码思路是给调度器加一层长度分桶：按序列长度区间分批，同桶内长度接近，填充浪费与块循环次数趋于一致；跨桶请求走独立批或延迟合并。代价是桶边界处的请求等待时间上升，桶过细则批大小不足、算力利用率下降。</p>\n<p>工程判断落在桶粒度与 SLO 的权衡上：首 token 延迟敏感的负载应把长序列请求隔离到独立批，避免污染短请求的尾延迟；吞吐优先的负载可放宽桶边界，用更大的批摊薄填充浪费。具体例子是分离式预填/解码部署中，预填阶段按长度分桶、解码阶段按 KV cache 占用分桶，两段使用不同的桶策略，预填的尾延迟不再传导到解码的批调度。监控应记录每批的块循环次数与完成时间分位数，尾延迟突增时先看批内长度方差，再看块尺寸是否因 SRAM 约束被压低。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-40\">四十 · 静默降级：收益消失而不报错</h3>\n<p>静默降级是 FlashAttention 部署中最难捕获的失败模式：算子仍输出正确结果，但分块收益消失，端到端延迟不降反升。触发条件有三类。第一类是短序列：序列短到块数很少，重计算与调度开销超过 HBM 读写节省，分块算子比标准实现更慢。第二类是算力受限场景：HBM 带宽相对算力不紧张时，分块减少的读写不构成瓶颈，额外的块调度与在线 softmax 重标定成为纯开销。第三类是块尺寸被 SRAM 约束压低后复用率下降，HBM 读写量回升到接近标准实现的水平。</p>\n<p>监控静默降级不能只看端到端延迟，要把延迟拆成 HBM 读写时间与算力时间。若 HBM 读写时间占比下降但总算力时间上升，说明分块在起作用但被重计算抵消；若两者都不变而端到端延迟上升，说明调度开销在起作用。判据可写成 <span class=\"formula-inline\">$$\\text{收益} \\propto \\frac{T_{\\text{HBM}}}{T_{\\text{compute}}}$$</span>，该比值越高，分块收益越明显；比值接近 1 时，分块与标准实现持平，重计算开销使其落后。定位方法是按序列长度分档跑基准，找出收益翻转的阈值区间，在该区间内切换回标准实现或改用不分块的小序列路径。</p>\n<p>回滚策略是长度感知的算子选择：短序列走标准注意力，长序列走分块算子，阈值由目标硬件实测确定而非引用论文数字。代价是维护两条路径与切换逻辑，切换点附近的请求可能因路径不同而出现延迟抖动。具体例子是同一模型服务混合长短请求，若不按长度分流，短请求被分块算子的固定开销拖慢，长请求的收益被短请求的尾延迟掩盖，整体 SLO 反而劣化。监控应记录分档后的吞吐与尾延迟，静默降级的信号是某档的吞吐低于标准实现基线。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-41\">四十一 · 监控面与回滚顺序</h3>\n<p>把上述失败模式收敛成一组可观测指标，按定位优先级排列。第一层是 HBM 读写量与算力利用率：读写量随序列长度线性增长是正常，若增长斜率变陡说明块尺寸被压低或填充浪费放大。第二层是片上占用与块调度空转：占用溢出与空转同时上升指向 SRAM 约束。第三层是批内长度方差与块循环次数方差：方差失配指向批抖动。第四层是逐层输出误差与量化档位：误差随块数增长指向在线 softmax 重标定路径。第五层是分档吞吐对比：某档吞吐低于标准实现基线即为静默降级。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>首要观测量</th><th>定位手段</th><th>回滚动作</th></tr></thead><tbody><tr><td>精度塌陷</td><td>逐层输出误差随块数增长</td><td>关闭量化对比参考实现</td><td>降量化档位或提高累加器精度</td></tr><tr><td>HBM OOM</td><td>批内 KV cache 与激活叠加</td><td>降批内并发逐批复现</td><td>降并发或改分页 KV 布局</td></tr><tr><td>SRAM 溢出</td><td>占用溢出与读写量突增</td><td>按硬件档位重测块尺寸</td><td>降块尺寸、接受复用率下降</td></tr><tr><td>批抖动</td><td>批内长度方差与尾延迟</td><td>长度分桶前后对比</td><td>长序列隔离到独立批</td></tr><tr><td>静默降级</td><td>分档吞吐低于标准基线</td><td>按序列长度分档跑基准</td><td>长度感知切换算子路径</td></tr></tbody></table>\n<p>回滚顺序遵循代价从低到高：先调批调度与分桶，不动算子；再调块尺寸与量化档位，接受吞吐损失；最后切换算子路径或降序列长度上限。每次回滚后必须重测 HBM 读写量与算力时间的比值，确认收益恢复而非仅延迟数字好看。具体机制上，回滚的判定点应绑定在分档吞吐与逐层误差两个信号上，前者捕获静默降级，后者捕获精度塌陷，两者同时恶化时优先处理精度，因为静默降级只损失吞吐而精度塌陷损失正确性。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-42\">四十二 · 分块算子的失效面：从 SRAM 溢出到端到端倒挂</h3>\n<p>FlashAttention 的边界不在数学，而在片上容量与带宽配比的耦合。块尺寸 $B_q\\times B_k$ 必须同时容纳 Q 块、K/V 块、局部分数块、累加器与运行统计量 $m_i,\\ell_i$，一旦片上驻留量越过 SRAM 上限，核函数要么溢出到本地内存使复用率崩塌，要么被迫缩小块尺寸，令 HBM 读写次数随块数线性上升。诊断时先看一个比值：每块实际 HBM 流量与理论下界之比，若显著大于 1，说明块太小、K/V 块被反复重载；若核内出现溢出计数或寄存器压力告警，说明块太大。这是典型的“两头都不讨好”区间，调参只能逐硬件档位实测，不能跨档照搬。</p>\n<p>第二类失效是端到端倒挂。分块收益正比于 HBM 读写占比，短序列或算力受限时，重计算与块调度开销会吃掉收益，表现为单请求延迟不降反升。定位方法是把一次注意力调用的时间拆成块乘、在线 softmax 重标定、HBM 读写三段，观察重标定占比随序列长度的变化；若短序列段重标定与调度占比压过读写节省，就应设序列长度阈值走标准路径。批抖动与尾延迟同源：批内序列长度不齐时按最长序列分块，短请求被迫填充，块数由最长者决定，尾延迟被最长请求拖住。监控需按分位数看块数与填充率，而非只看均值。</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{T_{\\text{std}}}{T_{\\text{blk}}+T_{\\text{recalc}}+T_{\\text{sched}}},\\quad T_{\\text{blk}}\\propto \\frac{N^2}{B_qB_k}\\cdot\\text{HBM bytes per block}$$</div>\n<p>精度塌陷与静默降级要分开归因。该算子为精确注意力，本身不引入近似，因此数值异常只可能来自三处：在线 softmax 重标定时 $m_i$ 更新与已累加分子项的重缩放顺序错位、块内累加精度不足（尤其与 FP8/NVFP4 组合时）、以及量化误差被误记为分块机制的问题。监控应比对分块输出与整块参考输出在相同输入上的最大偏差，并单独记录量化路径的误差预算；一旦偏差越过阈值即回滚到未量化或更小块尺寸的稳定配置。回滚策略按代价排序：先降块尺寸恢复驻留，再关量化路径，最后退回标准注意力路径，避免一次性改动过多变量导致无法定位。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要怀疑</th><th>定位信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>吞吐骤降</td><td>块过小、K/V 重载</td><td>每块 HBM 流量/理论下界</td><td>逐档放大块尺寸</td></tr><tr><td>核内溢出</td><td>块过大越 SRAM</td><td>溢出计数、寄存器压力</td><td>缩块或拆统计量</td></tr><tr><td>尾延迟抬升</td><td>变长批填充</td><td>块数分位数、填充率</td><td>按长度分桶调度</td></tr><tr><td>输出偏差</td><td>重标定顺序/量化</td><td>与整块参考的最大偏差</td><td>关量化或退回标准路径</td></tr></tbody></table>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-43\">四十三 · 基准口径的第一原则：先固定“被测量”，再谈数字</h3>\n<p>FlashAttention 的论文材料没有给出可核验的加速比、显存下降数值与序列长度阈值，这一点决定了本部分不能写成“数字对照表”，而要写成“口径对照表”。读任何一份 FlashAttention 基准报告，第一件事不是看倍数，而是确认它测的是哪一层：算子级 microbenchmark（单次注意力调用的核函数耗时）、层内端到端（含前后处理与 HBM 往返）、还是请求级服务指标（TTFT/TPOT/吞吐）。三者不可互换。算子级测的是分块与在线 softmax 在 SRAM 约束下的 HBM 读写节省；请求级测的是这套节省在批调度、KV cache 分页、连续批处理叠加后还剩多少。工程上常见的误读是把算子级的倍数直接当成服务吞吐的倍数，忽略了调度器与显存布局会稀释收益。</p>\n<p>口径必须同时钉死五个变量：模型与序列长度分布、硬件档位（SRAM 容量与 HBM 带宽比）、batch 与并发、指标定义、以及是否开启量化。任何一个变量变动，数字就进入另一条不可比的轨道。下面逐项拆。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-44\">四十四 · 模型与序列长度：收益的定义域</h3>\n<p>FlashAttention 的收益来自把完整注意力矩阵从 HBM 读写路径上移除，因此收益大小由“HBM 读写占总时间比例”决定，而这个比例随序列长度单调上升。标准实现的 HBM 流量与显存占用随序列长度平方增长，分块实现只读写 Q、K、V、O 与 softmax 统计量，流量与序列长度线性相关。于是基准报告里的序列长度分布就是收益的定义域：短序列请求占比高的负载，分块带来的节省会被核内调度与重计算开销吃掉；长序列占主导的负载才是这套算子的靶场。</p>\n<div class=\"formula\">$$\\text{HBM 流量}_{\\text{标准}} \\propto N^2,\\qquad \\text{HBM 流量}_{\\text{分块}} \\propto N$$</div>\n<p>具体例子：同一份基准若把序列长度从“以短请求为主”换成“以长请求为主”，即使硬件、batch、指标全不变，报告出的加速比也会显著不同——这不是测量误差，而是被测对象的定义域变了。因此引用任何 FlashAttention 数字时，必须附带序列长度分布（均值、P99、以及长序列请求占比），否则该数字无法迁移到自己的容量规划。</p>\n<p>另一个不可比点是模型结构：注意力在解码阶段是逐 token 的增量形式，Q 只有一行，分块策略退化为 KV cache 分块读取，收益主要落在 KV 带宽而非 O(N²) 矩阵消除上。预填阶段才是完整矩阵形态。把预填阶段的算子级数字套到解码阶段，是把两种不同的内存访问形态混为一谈。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-45\">四十五 · 硬件档位：SRAM 容量与带宽配比决定块尺寸，块尺寸决定一切</h3>\n<p>分块尺寸受片上 SRAM 容量硬约束：块过大无法驻留导致溢出，块过小则数据复用率与并行度下降。这意味着同一份核函数在不同硬件档位上不是“同一实验”，因为块尺寸必须逐档调参。Blackwell 档位（SM100/SM103）上，SRAM 容量、HBM 带宽与算力的配比与论文成文时的档位不同，直接照搬论文块尺寸会出现占用溢出或复用率下降，基准数字随之失真。</p>\n<p>基准报告必须写明：块尺寸如何选定（按 SRAM 容量推导还是实测扫描）、是否发生片上占用溢出、以及 HBM 读写量是否被实际观测（而非仅由理论流量推算）。工程代价在这里体现为调参成本：每个硬件档位都要重跑块尺寸扫描，扫描空间受 SRAM 上限压缩，调参自由度有限。若报告只给一个“最优块尺寸”而不给档位与扫描方法，该数字对其他档位没有参考价值。</p>\n<p>与量化组合时口径再变一次：NVFP4/FP8 改变块内累加精度与在线 softmax 的数值稳定边界，量化后的块尺寸与重标定频率需重新评估。此时测得的加速比是“分块 + 量化”的合成结果，不能归因于分块机制单独作用——这正是把精确注意力与近似方法混谈的典型错误。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-46\">四十六 · batch 与并发：填充浪费与 SRAM 驻留压力</h3>\n<p>批大小影响 Q 块并行度。批内序列长度不齐时需按最长序列分块，短请求被填充到最长长度，产生填充浪费；这部分算力与带宽开销会计入吞吐分母，使报告出的吞吐偏低。并发上升时片上 SRAM 与寄存器压力增大，需限制同时驻留的块数以避免占用溢出，于是并发与块尺寸之间存在此消彼长：并发越高，可用的每请求块尺寸越小，单请求内的数据复用率下降。</p>\n<ul>\n<li>口径要求：报告 batch 时必须同时给 batch 内序列长度的分布（是否变长、填充比例），否则吞吐数字不可比。</li>\n<li>口径要求：报告并发时必须说明是否触发了 SRAM 驻留限制、块尺寸是否随并发下调。</li>\n<li>口径要求：区分“静态批”与“连续批处理”，后者在请求到达不均时吞吐与尾延迟的表现不同，前者数字不能迁移。</li>\n</ul>\n<p>具体例子：一个以固定长度合成的静态批基准，其吞吐数字在真实变长负载下会因填充浪费与块尺寸下调而下降；这不是实现退化，而是基准没有覆盖变长批这一维度。容量规划若直接引用静态批吞吐，会高估可承载并发。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-47\">四十七 · 指标：TTFT、TPOT、吞吐、显存、功耗各自的陷阱</h3>\n<p>TTFT（首 token 延迟）在预填阶段由长序列注意力的 HBM 读写主导，分块算子在此处收益最直接；但 TTFT 也受调度排队影响，基准若在空载下测 TTFT，得到的是算子下限而非服务上限。TPOT（每输出 token 时间）在解码阶段由 KV cache 带宽主导，与分块算子的关系是间接的——它通过 KV 分块布局影响带宽，而非通过消除 O(N²) 矩阵。把预填阶段的 TTFT 改善当成 TPOT 改善，是两类指标混用。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>主要受什么支配</th><th>分块算子的作用路径</th><th>常见误读</th></tr></thead><tbody><tr><td>TTFT</td><td>预填阶段 HBM 读写 + 排队</td><td>直接：消除完整注意力矩阵落盘</td><td>空载测量当成服务上限</td></tr><tr><td>TPOT</td><td>解码阶段 KV 带宽</td><td>间接：KV 分块布局</td><td>把预填收益套到解码</td></tr><tr><td>吞吐</td><td>batch 构成 + 调度 + 填充</td><td>稀释：调度开销摊薄算子收益</td><td>算子级倍数当成服务倍数</td></tr><tr><td>显存</td><td>O(N²) 矩阵是否落盘 + KV cache</td><td>直接：平方级降为线性级</td><td>忽略 KV cache 仍占大头</td></tr><tr><td>功耗</td><td>HBM 读写活动 + 算力占用</td><td>减少 HBM 活动，增加重计算算力</td><td>只看时间不看能量</td></tr></tbody></table>\n<p>显存指标要拆两层：注意力中间矩阵的显存（分块后从平方级降为线性级）与 KV cache 的显存（由批大小、序列长度、层数决定，分块算子不直接改变其总量，只改变其访问形态）。报告“显存下降”若不说明是哪一层，读者会误以为 KV cache 也同步缩小。功耗指标同理：分块减少 HBM 读写活动，但反向重计算增加算力占用，推理场景下没有反向，功耗收益主要来自 HBM 活动下降；若基准包含训练步骤，功耗口径完全不同。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-48\">四十八 · 哪些提升不可比：一张负面清单</h3>\n<p>以下情形下的 FlashAttention 数字互相不可比，工程判断应直接拒绝引用：</p>\n<ul>\n<li>序列长度分布不同（短请求主导 vs 长请求主导），收益定义域不同。</li>\n<li>硬件档位不同且块尺寸未逐档重调，SRAM 与带宽配比变化使最优块尺寸漂移。</li>\n<li>batch 构成不同（定长静态批 vs 变长连续批），填充浪费与 SRAM 驻留压力不同。</li>\n<li>指标层级不同（算子级 microbenchmark vs 请求级服务指标），调度与显存布局的稀释程度不同。</li>\n<li>叠加了量化或稀疏化，测得的加速是合成结果，不能归因于分块机制。</li>\n<li>基线不是同一数学结果的标准注意力实现，精确算子与近似方法的对比本身不成立。</li>\n</ul>\n<p>材料未给出消融细节，但可推断的消融维度是块大小选择、是否重计算、是否融合在线 softmax；引用任何数字前应确认这三项是否被单独隔离。若报告只给一个总倍数而不给消融，就无法判断收益来自分块本身还是来自算子融合等伴随优化。</p>\n<p>工程判断落在最后一步：论文数字不能直接进入容量规划，必须在目标硬件档位、目标序列长度分布、目标 batch 形态下实测，并同时记录 HBM 读写量、片上占用溢出与块调度空转这三项观测量——它们才是把“分块收益”与“调度开销”区分开的证据。基准的价值不在于倍数，而在于它是否把被测对象的定义域钉死到可以复现。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-49\">四十九 · 基准口径：分块注意力的收益边界与不可比数字</h3>\n<p>把 FlashAttention 的收益读成“长序列一定更快”是口径错误。它的收益来自 HBM 读写占比，而非矩阵乘算力：标准实现把完整注意力矩阵写回 HBM，显存 O(N²)、读写量随序列长度增长；分块算子只让 Q、K、V、O 与 softmax 统计量进出 HBM。因此同一算子在不同负载下的端到端表现由带宽瓶颈程度决定，短序列或算力受限场景中，重计算与核内调度开销会抵消分块收益，延迟不降反升。读数字时先问三件事：序列长度分布、batch 内长度是否齐整、硬件档位的 SRAM 容量与 HBM 带宽配比——三者任一变化，同一组 TTFT/TPOT 与吞吐都不可直接横比。</p>\n<p>块尺寸是硬约束下的调参，不是可移植常数。设片上可用 SRAM 为 S，块内需驻留 Q 块、K/V 块、局部分数块与运行统计量，粗略约束为 <span class=\"formula\">$$B_q B_k\\,(d_{\\text{head}}+c)\\ \\lesssim\\ S$$</span> 其中 c 为分数块与统计量的额外占用。块过大溢出、块过小复用率与并行度下降，且不同档位 SRAM 与带宽配比不同，必须逐档实测。批内序列长度不齐时按最长序列分块，填充浪费直接吃掉吞吐；并发上升时片上占用与寄存器压力增大，需限制同时驻留块数。这些代价在基准表里通常不体现，却决定尾延迟。</p>\n<p>指标要分开读：TTFT 受预填阶段分块调度与 HBM 读写影响，TPOT 受解码阶段 KV cache 布局与带宽影响，吞吐受批调度与块并行度影响，显存看的是峰值而非均值，功耗则随带宽利用率与占用溢出波动。下表给出可比性判断的口径，而非具体数值。</p>\n<table class=\"mini\"><thead><tr><th>变量</th><th>变化时哪些数字不可比</th><th>原因</th></tr></thead><tbody><tr><td>序列长度分布</td><td>吞吐、TTFT</td><td>带宽瓶颈程度改变，短序列重计算开销占比上升</td></tr><tr><td>batch 内长度齐整度</td><td>吞吐、显存峰值</td><td>按最长序列分块产生填充浪费</td></tr><tr><td>硬件档位（SRAM/带宽配比）</td><td>全部指标</td><td>块尺寸需逐档重调，溢出与复用率不同</td></tr><tr><td>是否与量化/KV 分页组合</td><td>精度与显存</td><td>精确注意力不引入近似，量化误差需单独归因</td></tr></tbody></table>\n<p>材料未给出可核验的加速比、显存下降数值与序列长度阈值，容量规划不能直接引用论文数字。该算子为精确注意力，可与 KV cache 分页、批调度正交组合，但组合后需重估 SRAM 占用与在线 softmax 的数值稳定；把量化或稀疏化带来的误差归因于分块机制，是把两类口径混谈。工程判断应落在：在目标硬件上以真实长度分布实测块尺寸与并发上限，再决定是否启用重计算路径。</p>\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-50\">五十 · 迁移到解码阶段：Q 块退化为单行，收益结构反转</h3>\n<p>把 FlashAttention 的分块前向直接搬到自回归解码，会立刻遇到形状失配。预填阶段 Q 是 N×d 的行块，K、V 是 N×d 的列块，块乘的算术强度足够高，HBM 读写被压到与序列长度线性相关；解码阶段每步只有一行 Q（或 batch 内每请求一行），K、V 却随上下文线性增长。此时分块仍然成立，但块内矩阵乘退化为向量-矩阵乘，算术强度骤降，片上 SRAM 里驻留的 K、V 块复用次数从「一个 Q 块乘一遍」变成「一行 Q 乘一遍」，数据搬运与计算的比例重新倒向带宽一侧。</p>\n<p>代价的具体形态是：单步解码的延迟由 K、V 的读取量主导，分块只改变了读取的组织方式，没有改变读取总量。工程判断是——解码阶段的优化重心必须从「避免物化注意力矩阵」转向「避免重复读取 KV cache」，也就是分页 KV、KV 量化、GQA/MLA 这类压缩 KV 维度的手段，而不是继续调 FlashAttention 的块尺寸。分块在这里的价值退化为两点：一是让单行 Q 与 KV 块的乘加保持在片上完成，省掉中间分数的 HBM 往返；二是让变长批内不同长度的请求能以块为单位对齐，减少填充。</p>\n<p>一个具体例子：批内同时存在长度差异很大的请求时，按最长序列分块会让短请求的 Q 块大量空转。可行的改法是按请求的实际块数调度，把 Q 块循环放到外层、KV 块循环放到内层，让不同请求的块交错填充 SM 的空闲周期——这本质上是把论文的核内循环顺序当作调度原语来用，而不是照搬其块尺寸。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-51\">五十一 · 迁到变长批与连续批处理：块边界与调度器必须对齐</h3>\n<p>论文的分块假设序列是规整的定长张量。连续批处理下，每个请求的 KV 长度随时间增长，批组成每步都在变。若调度器按 token 粒度拼接 KV，而注意力核按固定块尺寸切分，块边界就会跨越不同请求的 KV 区域，导致一次块乘读到不属于同一请求的数据。这不是数值错误，而是掩码与边界处理的成本上升：需要在块内做请求归属判断，或在 KV 布局上保证每个请求的 KV 起始地址按块对齐。</p>\n<p>伪代码层面的判断是：调度器分配 KV 页时，页大小应取分块尺寸的整数倍，使一个 KV 块恰好落在若干页内；注意力核的块循环以页为步长，块内不再做跨请求切分。这样做的代价是页内碎片——短请求末尾不足一页时浪费显存，碎片率上界为「页大小减一」个 token 的 KV 占用。工程上要接受这个碎片，换取核内循环无分支。</p>\n<div class=\"formula\">$$\\text{碎片率}\\le \\frac{(P-1)\\cdot s_{\\text{kv}}}{L\\cdot s_{\\text{kv}}}=\\frac{P-1}{L}$$</div>\n<p>其中 P 为页大小（以 token 计），L 为请求长度，s_kv 为每 token 的 KV 字节数。L 远大于 P 时碎片可忽略；L 与 P 同量级时碎片显著，此时应缩小页大小或改为按请求独立分块。这是迁移到连续批处理时最容易被忽略的一笔显存账。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-52\">五十二 · 迁到量化与低精度：在线 softmax 的数值边界要重估</h3>\n<p>论文的在线 softmax 依赖运行最大值 m 与运行归一化因子 l 的重标定，其数值稳定性建立在分数以较高精度累加的前提上。迁到 FP8 或 NVFP4 时，块内矩阵乘的输入被量化，分数误差进入指数项，重标定时已累加分子项被乘以一个指数缩放因子，误差随之放大。判断是：低精度下不能只量化 Q、K、V 而保留 softmax 统计量的高精度假设，必须把 m 与 l 的更新路径单独保持在较高精度（如 FP32 累加），否则长序列上 l 的相对误差会随块数累积。</p>\n<p>代价体现在两处：一是累加器精度提高会占用更多寄存器与 SRAM，压缩了可用于 KV 块的片上容量，块尺寸被迫调小，复用率下降；二是量化后的分数分布更集中，运行最大值的更新频率下降，重标定次数减少，反而降低了在线 softmax 的开销——这两股力量方向相反，净收益必须在目标硬件上实测，不能从论文的精确注意力结论外推。</p>\n<p>具体例子：把 KV 量化为 FP8 后，块内乘加的输出若直接以 FP8 送入指数，尾块的长序列累积误差会表现为输出范数偏移；改法是在块内用 FP16 或 FP32 累加分数，仅在写回 O 时降精度，这与论文「统计量不落盘、只在片上维护」的结构是兼容的，但要求核内为累加器单独预留片上空间。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-53\">五十三 · 迁到多卡与分离式部署：分块边界与通信粒度耦合</h3>\n<p>序列并行把长序列切到多卡，每卡持有部分 Q 与部分 KV。FlashAttention 的块循环在单卡内是自洽的，跨卡后每个 Q 块需要看到全部 KV 块，块乘的输入来自远端。此时分块尺寸不再只由 SRAM 容量决定，还由通信粒度决定：块太小则每块触发一次集合通信，通信启动开销压过计算；块太大则单次通信的数据量超出链路缓冲，流水被打断。</p>\n<p>判断是：在 NVLink 域内做序列并行时，块尺寸应取「一次通信能覆盖多个块乘」的量级，把通信与计算重叠在块循环的流水里；跨域（如分离式预填/解码之间走 NIXL）时，传输的是 KV 块而非分数块，分块边界必须与 KV 传输的页边界一致，否则接收端要重新切分，等于把分块收益还回去。代价是流水深度受限于链路带宽与缓冲，长序列下通信占比随卡数上升，分块带来的 HBM 节省会被跨卡搬运抵消一部分。</p>\n<p>具体例子：预填节点按块算出 KV 并以块为单位传给解码节点，解码节点的注意力核直接以收到的块为循环单元，不再重新分块。这样做的显存代价是解码端要按块预留 KV 缓冲，缓冲深度决定可容忍的传输抖动，深度不足时解码步会等待 KV 到达，尾延迟变差。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-54\">五十四 · 规模上限与不适用场景：三条硬边界</h3>\n<p>第一条边界是 SRAM 容量。块尺寸的上限由片上 SRAM 决定，而块尺寸下限由复用率决定，两者之间是可调窗口。序列越长，KV 块数越多，窗口本身不变，但每块的固定开销（循环控制、统计量更新）被摊薄，收益上升；序列短到块数接近 1 时，分块退化为整块计算，重计算与调度开销纯属额外负担。这条边界决定了该方案在短序列、小模型上的不适用。</p>\n<p>第二条边界是带宽瓶颈程度。分块收益正比于「被省掉的 HBM 读写量」占原总时间的比例。若目标负载的算力已接近饱和、带宽相对充裕，省下的读写换不来等比例的延迟下降，反而因核内循环的调度开销略微变慢。判断依据是实测的带宽利用率与算力利用率之比，而不是序列长度本身。</p>\n<p>第三条边界是精确性假设。该算子不引入近似，因此不能与稀疏化、低秩近似混谈；迁到这些方法时，分块只是承载近似的容器，误差来源是近似本身而非分块。把两者混在一起调参，会在误差归因上失焦——这是迁移到扩散类、长文档类负载时最常见的误判。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>必须改的部分</th><th>主要代价</th></tr></thead><tbody><tr><td>解码阶段</td><td>循环顺序改为 KV 外层、Q 行内层；重心转向 KV 压缩</td><td>单步延迟由 KV 读取量主导，分块不改读取总量</td></tr><tr><td>连续批处理</td><td>KV 页大小取块尺寸整数倍，核内不做跨请求切分</td><td>页内碎片，上界 (P−1)/L</td></tr><tr><td>低精度量化</td><td>m、l 与块内分数累加保持高精度</td><td>累加器占片上空间，块尺寸被迫调小</td></tr><tr><td>多卡/分离式</td><td>块尺寸与通信粒度、KV 传输页边界对齐</td><td>流水深度受链路带宽与缓冲限制</td></tr></tbody></table>\n<p>落到工程判断上：这套分块方案的可迁移性来自它的结构——统计量在片上维护、中间矩阵不落盘、块循环可重排——而不是来自它的具体块尺寸。迁到任何新负载，第一步都是重算「块尺寸窗口」与「带宽/算力比」这两个量，第二步才是决定是否保留重计算路径。窗口窄、比值低的场景，直接退回整块实现更省事；窗口宽、比值高的场景，才值得把块循环与调度器、KV 布局、通信粒度一起对齐。</p>\n\n<h3 id=\"paper-flashattention-fast-and-memory-effic-2022-sec-55\">五十五 · 迁移边界：分块收益在何处失效</h3>\n<p>把 FlashAttention 的分块范式搬到别的模型上，第一道闸门不是数学而是 SRAM 容量与 HBM 带宽的比值。块尺寸 B<sub>c</sub> 必须同时容纳 K/V 列块、局部分数块与运行统计量 m、l，片上驻留量约正比于 B<sub>r</sub>·B<sub>c</sub>·d 的元素数；一旦超出 SRAM，核函数要么溢出回退到 HBM 写分数块，要么缩小块尺寸，而后者直接压低数据复用率与并行度。判断准则可以写成一个比值：只有当“每块 HBM 流量 / 每块乘加算力”明显高于硬件的带宽算力比时，分块才划算。Blackwell 档位上 NVFP4/FP8 把矩阵乘算力抬得更高，同一序列长度下带宽相对更紧，收益窗口反而变宽；但量化后块内累加精度与在线 softmax 的重标定数值稳定性要重估，误差不能归因于分块机制本身。</p>\n<p>第二类失效来自负载形态而非硬件。短序列请求下，重计算与核内循环调度的固定开销可能抵消 HBM 读写节省，端到端延迟不降反升；批内序列长度不齐时按最长序列分块会产生填充浪费，并发上升又挤压片上驻留块数。因此迁移到解码阶段或变长批服务时，不能照搬预填阶段的块尺寸，需按实际序列长度分布逐档实测。该算子为精确注意力，可与 KV cache 分页、连续批处理正交组合，但组合后 SRAM 占用被 KV 分页元数据与并发块数共同分摊，块尺寸调参空间进一步收窄。</p>\n<p>规模上限体现在两个方向。序列维度上，显存从平方级降为线性级只解决了“存得下”，HBM 读写仍随序列长度线性增长，超长上下文下瓶颈从注意力矩阵转移到 KV 本身，分块算子无法单独突破；并行维度上，材料未给出多卡切分方案，长序列若走序列并行，分块边界必须与切分边界对齐，否则跨卡归约的通信量会吃掉 IO 收益。工程判断是：把该方案当作算子级范式而非容量承诺，部署前在目标硬件上实测 HBM 读写量、片上占用溢出与块调度空转，容量规划不引用论文数字。</p>\n<table class=\"mini\"><thead><tr><th>迁移场景</th><th>主要改动</th><th>系统代价</th></tr></thead><tbody><tr><td>短序列/解码</td><td>缩小块尺寸或回退标准核</td><td>调度开销占比上升，延迟可能不降</td></tr><tr><td>FP8/NVFP4 量化</td><td>重估块内累加与在线 softmax 稳定性</td><td>数值误差需单独评估</td></tr><tr><td>多卡序列并行</td><td>分块边界对齐切分边界</td><td>跨卡归约通信占用带宽</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">FlashAttention: Fast and </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Memory-Efficie…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2022 · arXiv preprint</text></svg><figcaption><b>家谱</b> · FlashAttention: Fast an… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称、长序列注意力基准（材料未给出细节）</td></tr><tr><td>基线</td><td>标准注意力实现（材料未给出具体基线名）</td></tr><tr><td>主要结果</td><td>材料未给出可核验的加速比、显存下降数值或序列长度阈值；论文主张在不改变数学…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节；可推断的消融维度为块大小选择、是否重计算、是否融合…</td></tr><tr><td>局限</td><td>分块尺寸受片上 SRAM 容量约束，块过大无法驻留、块过小则并行度与复用下…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-flashattention-fast-and-memory-effic-2022 · 共 9 个片段</p>\n";break;}}})();
